insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (36, 2, 253, 257, 'سورة البقرة ٢٥٣ – ٢٥٧', 'تفاضل الرسل، وآية الكرسي، ولا إكراه في الدين', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 36) = $j$[{"lbl": "الآيتان ٢٥٣ – ٢٥٤", "q": "۞تِلۡكَ ٱلرُّسُلُ فَضَّلۡنَا بَعۡضَهُمۡ عَلَىٰ بَعۡضٖۘ مِّنۡهُم مَّن كَلَّمَ ٱللَّهُۖ وَرَفَعَ بَعۡضَهُمۡ دَرَجَٰتٖۚ وَءَاتَيۡنَا عِيسَى ٱبۡنَ مَرۡيَمَ ٱلۡبَيِّنَٰتِ وَأَيَّدۡنَٰهُ بِرُوحِ ٱلۡقُدُسِۗ وَلَوۡ شَآءَ ٱللَّهُ مَا ٱقۡتَتَلَ ٱلَّذِينَ مِنۢ بَعۡدِهِم مِّنۢ بَعۡدِ مَا جَآءَتۡهُمُ ٱلۡبَيِّنَٰتُ وَلَٰكِنِ ٱخۡتَلَفُواْ فَمِنۡهُم مَّنۡ ءَامَنَ وَمِنۡهُم مَّن كَفَرَۚ وَلَوۡ شَآءَ ٱللَّهُ مَا ٱقۡتَتَلُواْ وَلَٰكِنَّ ٱللَّهَ يَفۡعَلُ مَا يُرِيدُ ﴿٢٥٣﴾ يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ أَنفِقُواْ مِمَّا رَزَقۡنَٰكُم مِّن قَبۡلِ أَن يَأۡتِيَ يَوۡمٞ لَّا بَيۡعٞ فِيهِ وَلَا خُلَّةٞ وَلَا شَفَٰعَةٞۗ وَٱلۡكَٰفِرُونَ هُمُ ٱلظَّـٰلِمُونَ ﴿٢٥٤﴾", "w": [["تلك الرسل", "أولئك الرسل الذين قصّ الله على رسوله بعضاً منهم، وأخبره أنه منهم بقوله: «وإنك لمن المرسلين»."], ["من كلّم الله", "كموسى ﵇."], ["ورفع بعضهم درجات", "وهو محمد ﷺ، فضّله الله على سائر الرسل."], ["البينات", "المعجزات الدالة على صدق عيسى ﵇ في نبوته ورسالته."], ["روح القدس", "جبريل ﵇، كان يؤيّد عيسى ﵇ ويقوّيه."], ["اقتتلوا", "قتل بعضهم بعضاً."], ["أنفقوا مما رزقناكم", "النفقة الواجبة وهي الزكاة، ونفقة التطوع المستحبة."], ["لا بيع فيه", "لا يشتري أحد نفسه بمال يدفعه فداءً لها من العذاب."], ["ولا خُلّة", "ولا صداقة تنفع صاحبها."], ["ولا شفاعة", "تُقبل، إلا أن يأذن الله لمن يشاء ويرضى."]], "m": "بعد قصة ملأ بني إسرائيل، وهي قصة لا يعلمها أمّيّ مثل محمد ﷺ إلا بوحي، ختمها الله بتقرير رسالته: «وإنك لمن المرسلين». ثم أخبر أن الرسل فضّل بعضهم على بعض: فمنهم من كلّمه كموسى ﵇، ومنهم من اتخذه خليلاً كإبراهيم ﵇، ومنهم من آتاه الملك والحكمة وعلّمه صنعة الدروع كداود ﵇، ومنهم من سخّر له الجن وعلّمه منطق الطير كسليمان ﵇، ومنهم من آتاه البينات وأيّده بروح القدس وهو عيسى ﵇. ورفع نبينا محمداً ﷺ درجات: بعموم رسالته، وختم النبوة به، وتفضيل أمته، وما خصّه به من الشفاعة يوم القيامة. ثم أخبر أنه لو شاء هداية الناس لهداهم فلم يختلفوا ولم يقتتلوا بعد رسلهم، فهو يفعل ما يشاء ويحكم ما يريد.\nوفي الآية الثانية نادى المؤمنين وأمرهم بالإنفاق في سبيله قبل يوم القيامة؛ يوم لا فداء فيه ببيع وشراء، ولا صداقة تُجدي، ولا شفاعة تنفع، والكافرون بنعم الله وشرائعه هم الظالمون المستوجبون للعذاب والحرمان.", "h": ["تفاضل الرسل فيما بينهم بحسب جهادهم وصبرهم وما أهّلهم الله له من الكمال.", "صفة الكلام لله تعالى؛ إذ كلّم موسى ﵇ في الطور، وكلّم محمداً ﷺ في الملكوت الأعلى.", "الكفر والإيمان، والهداية والضلال، والحرب والسلم، كل ذلك تبع لمشيئة الله وحكمته.", "ذم الاختلاف في الدين، وأنه مصدر شقاء وعذاب.", "وجوب الإنفاق في سبيل الله مما رزق الله عبده.", "التحذير من الغفلة، والأخذ بأسباب النجاة يوم القيامة، ومن أقواها الإيمان والعمل الصالح وإنفاق المال تقرباً إلى الله."], "k": "يومٌ لا بيع فيه ولا خُلّة… فما الذي أقدّمه اليوم مما رزقني الله قبل أن يأتي؟"}, {"lbl": "الآية ٢٥٥", "q": "ٱللَّهُ لَآ إِلَٰهَ إِلَّا هُوَ ٱلۡحَيُّ ٱلۡقَيُّومُۚ لَا تَأۡخُذُهُۥ سِنَةٞ وَلَا نَوۡمٞۚ لَّهُۥ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِۗ مَن ذَا ٱلَّذِي يَشۡفَعُ عِندَهُۥٓ إِلَّا بِإِذۡنِهِۦۚ يَعۡلَمُ مَا بَيۡنَ أَيۡدِيهِمۡ وَمَا خَلۡفَهُمۡۖ وَلَا يُحِيطُونَ بِشَيۡءٖ مِّنۡ عِلۡمِهِۦٓ إِلَّا بِمَا شَآءَۚ وَسِعَ كُرۡسِيُّهُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَۖ وَلَا يَـُٔودُهُۥ حِفۡظُهُمَاۚ وَهُوَ ٱلۡعَلِيُّ ٱلۡعَظِيمُ ﴿٢٥٥﴾", "w": [["الله", "عَلَمٌ على ذات الرب تبارك وتعالى."], ["لا إله إلا هو", "لا معبود بحق إلا الله؛ إذ هو الخالق الرازق المدبّر، وعبادة ما سواه باطلة."], ["الحيّ", "ذو الحياة العظيمة التي لا تكون لغيره، وهي مستلزمة للقدرة والإرادة والعلم والسمع والبصر والكلام."], ["القيّوم", "القائم بتدبير الملكوت كله علويّه وسفليّه، القائم على كل نفس بما كسبت."], ["كرسيّه", "الكرسي موضع القدمين، ولا يعلم كنهه إلا الله."], ["يؤوده", "يُثقله ويشقّ عليه."]], "m": "لما أخبر تعالى عن يوم القيامة وأنه لا بيع فيه ولا شفاعة، أخبر عن جلاله وكماله، وأنه المعبود بحق، وأن عبادته هي التي تنجّي من أهوال ذلك اليوم: «الله لا إله إلا هو»، «الحي القيوم»: دائم الحياة التي لم تُسبق بموت ولا يطرأ عليها موت، العظيم القيومية على كل شيء، ولولا قيوميته ما استقام من أمر العوالم شيء. «لا تأخذه سنة ولا نوم»: لأن النعاس والنوم صفتا نقص، وهو ذو الكمال المطلق، ومن ينام لا تتأتّى له القيومية على الخلائق. «له ما في السماوات وما في الأرض» خلقاً وملكاً وتصرفاً، و«من ذا الذي يشفع عنده إلا بإذنه»: فلا يشفع عنده أحد كائن من كان إلا بإذنه. «يعلم ما بين أيديهم وما خلفهم» لكمال علمه، «ولا يحيطون بشيء من علمه إلا بما شاء» لعجزهم. «وسع كرسيّه السماوات والأرض» لكمال ذاته، «ولا يؤوده حفظهما»، «وهو العليّ» الذي ليس فوقه شيء، القاهر الذي لا يغلبه شيء، «العظيم» الذي كل شيء أمام عظمته صغير حقير.", "h": ["أنها أعظم آية في كتاب الله، اشتملت على ثمانية عشر اسماً لله ما بين ظاهر ومضمر، وكلماتها خمسون كلمة، وجملها عشر جمل، كلها ناطقة بربوبيته وألوهيته وأسمائه وصفاته الدالة على كمال ذاته وعلمه وقدرته وعظيم سلطانه.", "تُستحب قراءتها بعد الصلاة المكتوبة، وعند النوم، وفي البيوت لطرد الشيطان."], "k": "أقرأ آية الكرسي كثيراً… فهل وقفت مرة على معنى «الحي القيوم» وأنا أطلب منه حاجتي؟"}, {"lbl": "الآيتان ٢٥٦ – ٢٥٧", "q": "لَآ إِكۡرَاهَ فِي ٱلدِّينِۖ قَد تَّبَيَّنَ ٱلرُّشۡدُ مِنَ ٱلۡغَيِّۚ فَمَن يَكۡفُرۡ بِٱلطَّـٰغُوتِ وَيُؤۡمِنۢ بِٱللَّهِ فَقَدِ ٱسۡتَمۡسَكَ بِٱلۡعُرۡوَةِ ٱلۡوُثۡقَىٰ لَا ٱنفِصَامَ لَهَاۗ وَٱللَّهُ سَمِيعٌ عَلِيمٌ ﴿٢٥٦﴾ ٱللَّهُ وَلِيُّ ٱلَّذِينَ ءَامَنُواْ يُخۡرِجُهُم مِّنَ ٱلظُّلُمَٰتِ إِلَى ٱلنُّورِۖ وَٱلَّذِينَ كَفَرُوٓاْ أَوۡلِيَآؤُهُمُ ٱلطَّـٰغُوتُ يُخۡرِجُونَهُم مِّنَ ٱلنُّورِ إِلَى ٱلظُّلُمَٰتِۗ أُوْلَـٰٓئِكَ أَصۡحَٰبُ ٱلنَّارِۖ هُمۡ فِيهَا خَٰلِدُونَ ﴿٢٥٧﴾", "w": [["لا إكراه في الدين", "لا يُكره المرء على الدخول في الدين، وإنما يعتنقه بإرادته واختياره."], ["الرشد", "الهدى الموصل إلى الإسعاد والإكمال."], ["الغيّ", "الضلال المفضي بالعبد إلى الشقاء والخسران."], ["الطاغوت", "كل ما صرف عن عبادة الله من إنسان أو شيطان أو غيرهما."], ["العروة الوثقى", "لا إله إلا الله محمد رسول الله."], ["لا انفصام لها", "لا تنفكّ ولا تنحلّ بحال من الأحوال."], ["الله وليّ الذين آمنوا", "متولّيهم بحفظه ونصره وتوفيقه."], ["الظلمات", "ظلمات الجهل والكفر."], ["النور", "نور الإيمان والعلم."], ["أولياؤهم الطاغوت", "المتولّون لهم الشياطين الذين زيّنوا لهم الكفر، فأخرجوهم من الإيمان إلى الكفر ومن العلم إلى الجهل."]], "m": "يخبر الله بعد ذكر صفات جلاله في آية الكرسي أنه لا إكراه في دينه، وذلك حين أراد بعض الأنصار إكراه من تهوّد أو تنصّر من أولادهم على الدخول في الإسلام. ولذا فإن أهل الكتابين ومن شابههم تُؤخذ منهم الجزية ويُقَرّون على دينهم، أما الوثنيون الذين لا دين لهم سوى الشرك فيُقاتَلون حتى يدخلوا في الإسلام. ثم أخبر أنه بإنزال كتابه وبعث رسوله قد تبيّن الهدى من الضلال والحق من الباطل؛ فمن يكفر بالطاغوت ويؤمن بالله فيشهد أن لا إله إلا الله وأن محمداً رسول الله فقد استمسك من الدين بأمتن عروة وأوثقها، ومن يُصرّ على الكفر فقد تمسك بأوهى من خيط العنكبوت، والله سميع لأقوال عباده عليم بنياتهم. ثم أخبر أنه وليّ المؤمنين يخرجهم من ظلمات الكفر والجهل إلى نور العلم والإيمان، وأن الكافرين أولياؤهم الطاغوت من شياطين الجن والإنس، زيّنوا لهم الباطل فأخرجوهم من النور إلى الظلمات، فكانوا أصحاب النار الخالدين فيها.", "h": ["لا يُكره أهل الكتابين ومن في حكمهم كالمجوس والصابئة على الدخول في الإسلام إلا باختيارهم، وتُقبل منهم الجزية فيُقَرّون على دينهم.", "الإسلام كله رشد، وما عداه ضلال وباطل.", "التخلّي عن الرذائل مقدَّم على التحلّي بالفضائل.", "معنى لا إله إلا الله: الإيمان بالله والكفر بالطاغوت.", "ولاية الله تُنال بالإيمان والتقوى.", "نصرة الله ورعايته لأوليائه دون أعدائه."], "k": "الكفر بالطاغوت قبل الإيمان بالله… فما الذي يصرفني عن ربي وأحتاج أن أتخلّى عنه أولاً؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 36;
insert into public.tdb_cards(topic, i, body) select 36, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيتان ٢٥٣ – ٢٥٤", "q": "۞تِلۡكَ ٱلرُّسُلُ فَضَّلۡنَا بَعۡضَهُمۡ عَلَىٰ بَعۡضٖۘ مِّنۡهُم مَّن كَلَّمَ ٱللَّهُۖ وَرَفَعَ بَعۡضَهُمۡ دَرَجَٰتٖۚ وَءَاتَيۡنَا عِيسَى ٱبۡنَ مَرۡيَمَ ٱلۡبَيِّنَٰتِ وَأَيَّدۡنَٰهُ بِرُوحِ ٱلۡقُدُسِۗ وَلَوۡ شَآءَ ٱللَّهُ مَا ٱقۡتَتَلَ ٱلَّذِينَ مِنۢ بَعۡدِهِم مِّنۢ بَعۡدِ مَا جَآءَتۡهُمُ ٱلۡبَيِّنَٰتُ وَلَٰكِنِ ٱخۡتَلَفُواْ فَمِنۡهُم مَّنۡ ءَامَنَ وَمِنۡهُم مَّن كَفَرَۚ وَلَوۡ شَآءَ ٱللَّهُ مَا ٱقۡتَتَلُواْ وَلَٰكِنَّ ٱللَّهَ يَفۡعَلُ مَا يُرِيدُ ﴿٢٥٣﴾ يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ أَنفِقُواْ مِمَّا رَزَقۡنَٰكُم مِّن قَبۡلِ أَن يَأۡتِيَ يَوۡمٞ لَّا بَيۡعٞ فِيهِ وَلَا خُلَّةٞ وَلَا شَفَٰعَةٞۗ وَٱلۡكَٰفِرُونَ هُمُ ٱلظَّـٰلِمُونَ ﴿٢٥٤﴾", "w": [["تلك الرسل", "أولئك الرسل الذين قصّ الله على رسوله بعضاً منهم، وأخبره أنه منهم بقوله: «وإنك لمن المرسلين»."], ["من كلّم الله", "كموسى ﵇."], ["ورفع بعضهم درجات", "وهو محمد ﷺ، فضّله الله على سائر الرسل."], ["البينات", "المعجزات الدالة على صدق عيسى ﵇ في نبوته ورسالته."], ["روح القدس", "جبريل ﵇، كان يؤيّد عيسى ﵇ ويقوّيه."], ["اقتتلوا", "قتل بعضهم بعضاً."], ["أنفقوا مما رزقناكم", "النفقة الواجبة وهي الزكاة، ونفقة التطوع المستحبة."], ["لا بيع فيه", "لا يشتري أحد نفسه بمال يدفعه فداءً لها من العذاب."], ["ولا خُلّة", "ولا صداقة تنفع صاحبها."], ["ولا شفاعة", "تُقبل، إلا أن يأذن الله لمن يشاء ويرضى."]], "m": "بعد قصة ملأ بني إسرائيل، وهي قصة لا يعلمها أمّيّ مثل محمد ﷺ إلا بوحي، ختمها الله بتقرير رسالته: «وإنك لمن المرسلين». ثم أخبر أن الرسل فضّل بعضهم على بعض: فمنهم من كلّمه كموسى ﵇، ومنهم من اتخذه خليلاً كإبراهيم ﵇، ومنهم من آتاه الملك والحكمة وعلّمه صنعة الدروع كداود ﵇، ومنهم من سخّر له الجن وعلّمه منطق الطير كسليمان ﵇، ومنهم من آتاه البينات وأيّده بروح القدس وهو عيسى ﵇. ورفع نبينا محمداً ﷺ درجات: بعموم رسالته، وختم النبوة به، وتفضيل أمته، وما خصّه به من الشفاعة يوم القيامة. ثم أخبر أنه لو شاء هداية الناس لهداهم فلم يختلفوا ولم يقتتلوا بعد رسلهم، فهو يفعل ما يشاء ويحكم ما يريد.\nوفي الآية الثانية نادى المؤمنين وأمرهم بالإنفاق في سبيله قبل يوم القيامة؛ يوم لا فداء فيه ببيع وشراء، ولا صداقة تُجدي، ولا شفاعة تنفع، والكافرون بنعم الله وشرائعه هم الظالمون المستوجبون للعذاب والحرمان.", "h": ["تفاضل الرسل فيما بينهم بحسب جهادهم وصبرهم وما أهّلهم الله له من الكمال.", "صفة الكلام لله تعالى؛ إذ كلّم موسى ﵇ في الطور، وكلّم محمداً ﷺ في الملكوت الأعلى.", "الكفر والإيمان، والهداية والضلال، والحرب والسلم، كل ذلك تبع لمشيئة الله وحكمته.", "ذم الاختلاف في الدين، وأنه مصدر شقاء وعذاب.", "وجوب الإنفاق في سبيل الله مما رزق الله عبده.", "التحذير من الغفلة، والأخذ بأسباب النجاة يوم القيامة، ومن أقواها الإيمان والعمل الصالح وإنفاق المال تقرباً إلى الله."], "k": "يومٌ لا بيع فيه ولا خُلّة… فما الذي أقدّمه اليوم مما رزقني الله قبل أن يأتي؟"}, {"lbl": "الآية ٢٥٥", "q": "ٱللَّهُ لَآ إِلَٰهَ إِلَّا هُوَ ٱلۡحَيُّ ٱلۡقَيُّومُۚ لَا تَأۡخُذُهُۥ سِنَةٞ وَلَا نَوۡمٞۚ لَّهُۥ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِۗ مَن ذَا ٱلَّذِي يَشۡفَعُ عِندَهُۥٓ إِلَّا بِإِذۡنِهِۦۚ يَعۡلَمُ مَا بَيۡنَ أَيۡدِيهِمۡ وَمَا خَلۡفَهُمۡۖ وَلَا يُحِيطُونَ بِشَيۡءٖ مِّنۡ عِلۡمِهِۦٓ إِلَّا بِمَا شَآءَۚ وَسِعَ كُرۡسِيُّهُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَۖ وَلَا يَـُٔودُهُۥ حِفۡظُهُمَاۚ وَهُوَ ٱلۡعَلِيُّ ٱلۡعَظِيمُ ﴿٢٥٥﴾", "w": [["الله", "عَلَمٌ على ذات الرب تبارك وتعالى."], ["لا إله إلا هو", "لا معبود بحق إلا الله؛ إذ هو الخالق الرازق المدبّر، وعبادة ما سواه باطلة."], ["الحيّ", "ذو الحياة العظيمة التي لا تكون لغيره، وهي مستلزمة للقدرة والإرادة والعلم والسمع والبصر والكلام."], ["القيّوم", "القائم بتدبير الملكوت كله علويّه وسفليّه، القائم على كل نفس بما كسبت."], ["كرسيّه", "الكرسي موضع القدمين، ولا يعلم كنهه إلا الله."], ["يؤوده", "يُثقله ويشقّ عليه."]], "m": "لما أخبر تعالى عن يوم القيامة وأنه لا بيع فيه ولا شفاعة، أخبر عن جلاله وكماله، وأنه المعبود بحق، وأن عبادته هي التي تنجّي من أهوال ذلك اليوم: «الله لا إله إلا هو»، «الحي القيوم»: دائم الحياة التي لم تُسبق بموت ولا يطرأ عليها موت، العظيم القيومية على كل شيء، ولولا قيوميته ما استقام من أمر العوالم شيء. «لا تأخذه سنة ولا نوم»: لأن النعاس والنوم صفتا نقص، وهو ذو الكمال المطلق، ومن ينام لا تتأتّى له القيومية على الخلائق. «له ما في السماوات وما في الأرض» خلقاً وملكاً وتصرفاً، و«من ذا الذي يشفع عنده إلا بإذنه»: فلا يشفع عنده أحد كائن من كان إلا بإذنه. «يعلم ما بين أيديهم وما خلفهم» لكمال علمه، «ولا يحيطون بشيء من علمه إلا بما شاء» لعجزهم. «وسع كرسيّه السماوات والأرض» لكمال ذاته، «ولا يؤوده حفظهما»، «وهو العليّ» الذي ليس فوقه شيء، القاهر الذي لا يغلبه شيء، «العظيم» الذي كل شيء أمام عظمته صغير حقير.", "h": ["أنها أعظم آية في كتاب الله، اشتملت على ثمانية عشر اسماً لله ما بين ظاهر ومضمر، وكلماتها خمسون كلمة، وجملها عشر جمل، كلها ناطقة بربوبيته وألوهيته وأسمائه وصفاته الدالة على كمال ذاته وعلمه وقدرته وعظيم سلطانه.", "تُستحب قراءتها بعد الصلاة المكتوبة، وعند النوم، وفي البيوت لطرد الشيطان."], "k": "أقرأ آية الكرسي كثيراً… فهل وقفت مرة على معنى «الحي القيوم» وأنا أطلب منه حاجتي؟"}, {"lbl": "الآيتان ٢٥٦ – ٢٥٧", "q": "لَآ إِكۡرَاهَ فِي ٱلدِّينِۖ قَد تَّبَيَّنَ ٱلرُّشۡدُ مِنَ ٱلۡغَيِّۚ فَمَن يَكۡفُرۡ بِٱلطَّـٰغُوتِ وَيُؤۡمِنۢ بِٱللَّهِ فَقَدِ ٱسۡتَمۡسَكَ بِٱلۡعُرۡوَةِ ٱلۡوُثۡقَىٰ لَا ٱنفِصَامَ لَهَاۗ وَٱللَّهُ سَمِيعٌ عَلِيمٌ ﴿٢٥٦﴾ ٱللَّهُ وَلِيُّ ٱلَّذِينَ ءَامَنُواْ يُخۡرِجُهُم مِّنَ ٱلظُّلُمَٰتِ إِلَى ٱلنُّورِۖ وَٱلَّذِينَ كَفَرُوٓاْ أَوۡلِيَآؤُهُمُ ٱلطَّـٰغُوتُ يُخۡرِجُونَهُم مِّنَ ٱلنُّورِ إِلَى ٱلظُّلُمَٰتِۗ أُوْلَـٰٓئِكَ أَصۡحَٰبُ ٱلنَّارِۖ هُمۡ فِيهَا خَٰلِدُونَ ﴿٢٥٧﴾", "w": [["لا إكراه في الدين", "لا يُكره المرء على الدخول في الدين، وإنما يعتنقه بإرادته واختياره."], ["الرشد", "الهدى الموصل إلى الإسعاد والإكمال."], ["الغيّ", "الضلال المفضي بالعبد إلى الشقاء والخسران."], ["الطاغوت", "كل ما صرف عن عبادة الله من إنسان أو شيطان أو غيرهما."], ["العروة الوثقى", "لا إله إلا الله محمد رسول الله."], ["لا انفصام لها", "لا تنفكّ ولا تنحلّ بحال من الأحوال."], ["الله وليّ الذين آمنوا", "متولّيهم بحفظه ونصره وتوفيقه."], ["الظلمات", "ظلمات الجهل والكفر."], ["النور", "نور الإيمان والعلم."], ["أولياؤهم الطاغوت", "المتولّون لهم الشياطين الذين زيّنوا لهم الكفر، فأخرجوهم من الإيمان إلى الكفر ومن العلم إلى الجهل."]], "m": "يخبر الله بعد ذكر صفات جلاله في آية الكرسي أنه لا إكراه في دينه، وذلك حين أراد بعض الأنصار إكراه من تهوّد أو تنصّر من أولادهم على الدخول في الإسلام. ولذا فإن أهل الكتابين ومن شابههم تُؤخذ منهم الجزية ويُقَرّون على دينهم، أما الوثنيون الذين لا دين لهم سوى الشرك فيُقاتَلون حتى يدخلوا في الإسلام. ثم أخبر أنه بإنزال كتابه وبعث رسوله قد تبيّن الهدى من الضلال والحق من الباطل؛ فمن يكفر بالطاغوت ويؤمن بالله فيشهد أن لا إله إلا الله وأن محمداً رسول الله فقد استمسك من الدين بأمتن عروة وأوثقها، ومن يُصرّ على الكفر فقد تمسك بأوهى من خيط العنكبوت، والله سميع لأقوال عباده عليم بنياتهم. ثم أخبر أنه وليّ المؤمنين يخرجهم من ظلمات الكفر والجهل إلى نور العلم والإيمان، وأن الكافرين أولياؤهم الطاغوت من شياطين الجن والإنس، زيّنوا لهم الباطل فأخرجوهم من النور إلى الظلمات، فكانوا أصحاب النار الخالدين فيها.", "h": ["لا يُكره أهل الكتابين ومن في حكمهم كالمجوس والصابئة على الدخول في الإسلام إلا باختيارهم، وتُقبل منهم الجزية فيُقَرّون على دينهم.", "الإسلام كله رشد، وما عداه ضلال وباطل.", "التخلّي عن الرذائل مقدَّم على التحلّي بالفضائل.", "معنى لا إله إلا الله: الإيمان بالله والكفر بالطاغوت.", "ولاية الله تُنال بالإيمان والتقوى.", "نصرة الله ورعايته لأوليائه دون أعدائه."], "k": "الكفر بالطاغوت قبل الإيمان بالله… فما الذي يصرفني عن ربي وأحتاج أن أتخلّى عنه أولاً؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (37, 2, 258, 260, 'سورة البقرة ٢٥٨ – ٢٦٠', 'من ولاية الله لأوليائه: إبراهيم والمارّ على القرية', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 37) = $j$[{"lbl": "الآية ٢٥٨", "q": "أَلَمۡ تَرَ إِلَى ٱلَّذِي حَآجَّ إِبۡرَٰهِـۧمَ فِي رَبِّهِۦٓ أَنۡ ءَاتَىٰهُ ٱللَّهُ ٱلۡمُلۡكَ إِذۡ قَالَ إِبۡرَٰهِـۧمُ رَبِّيَ ٱلَّذِي يُحۡيِۦ وَيُمِيتُ قَالَ أَنَا۠ أُحۡيِۦ وَأُمِيتُۖ قَالَ إِبۡرَٰهِـۧمُ فَإِنَّ ٱللَّهَ يَأۡتِي بِٱلشَّمۡسِ مِنَ ٱلۡمَشۡرِقِ فَأۡتِ بِهَا مِنَ ٱلۡمَغۡرِبِ فَبُهِتَ ٱلَّذِي كَفَرَۗ وَٱللَّهُ لَا يَهۡدِي ٱلۡقَوۡمَ ٱلظَّـٰلِمِينَ ﴿٢٥٨﴾", "w": [["ألم تر", "ألم ينتهِ إلى علمك يا رسولنا؟ والاستفهام للتعجب من الطاغية."], ["حاجّ", "جادل وخاصم."], ["في ربه", "في شأن ربه من وجوده وربوبيته وألوهيته."], ["آتاه الله الملك", "أعطاه الحكم والسيادة على أهل بلاده."], ["إبراهيم", "أبو الأنبياء الخليل ﵇، وكان هذا الحجاج قبل هجرته إلى الشام."], ["فبُهت الذي كفر", "انقطع عن الحجة متحيّراً مدهوشاً، وهو النمرود البابلي."]], "m": "لما ذكر الله ولايته لأوليائه، وأنه مؤيّدهم وناصرهم ومخرجهم من الظلمات إلى النور، ضرب لذلك مثلاً: ألم تر إلى الطاغية الذي أبطرته نعمة الملك فجادل إبراهيم ﵇ في ربه؟ إنه لأمر عجب! قال له إبراهيم: ربي الذي يحيي ويميت، فقال: أنا أحيي وأميت. فردّ عليه إبراهيم بحجة أخرى: إن ربي يأتي بالشمس من المشرق فأتِ بها أنت من المغرب، فاندهش وتحيّر وانقطع، وأيّد الله وليّه إبراهيم فانتصر. فهذا مثال لإخراج الله أولياءه من ظلمة الجهل إلى نور العلم.", "h": ["النعم تُبطر صاحبها إذا حُرم ولاية الله.", "نصرة الله لأوليائه وإلهامهم الحجة لخصم أعدائهم.", "إذا ظلم العبد ووالى الظلم حتى أصبح وصفاً له حُرم هداية الله فلا يهتدي أبداً.", "جواز المجادلة والمناظرة في إثبات العقيدة الصحيحة."], "k": "إذا أُعطيت قوة أو منصباً، هل يزيدني ذلك تواضعاً لله… أم يغريني بالكِبر كما أغرى النمرود؟"}, {"lbl": "الآية ٢٥٩", "q": "أَوۡ كَٱلَّذِي مَرَّ عَلَىٰ قَرۡيَةٖ وَهِيَ خَاوِيَةٌ عَلَىٰ عُرُوشِهَا قَالَ أَنَّىٰ يُحۡيِۦ هَٰذِهِ ٱللَّهُ بَعۡدَ مَوۡتِهَاۖ فَأَمَاتَهُ ٱللَّهُ مِاْئَةَ عَامٖ ثُمَّ بَعَثَهُۥۖ قَالَ كَمۡ لَبِثۡتَۖ قَالَ لَبِثۡتُ يَوۡمًا أَوۡ بَعۡضَ يَوۡمٖۖ قَالَ بَل لَّبِثۡتَ مِاْئَةَ عَامٖ فَٱنظُرۡ إِلَىٰ طَعَامِكَ وَشَرَابِكَ لَمۡ يَتَسَنَّهۡۖ وَٱنظُرۡ إِلَىٰ حِمَارِكَ وَلِنَجۡعَلَكَ ءَايَةٗ لِّلنَّاسِۖ وَٱنظُرۡ إِلَى ٱلۡعِظَامِ كَيۡفَ نُنشِزُهَا ثُمَّ نَكۡسُوهَا لَحۡمٗاۚ فَلَمَّا تَبَيَّنَ لَهُۥ قَالَ أَعۡلَمُ أَنَّ ٱللَّهَ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٞ ﴿٢٥٩﴾", "w": [["قرية", "مدينة لم يذكر الله اسمها، فلا يُبحث عنها لعدم جدوى معرفتها."], ["خاوية", "فارغة من سكانها، ساقطة عروشها على جدرانها."], ["آية", "علامة على قدرة الله على بعث الناس أحياء يوم القيامة."], ["ننشزها", "نرفعها ونجمعها لتكون حماراً كما كانت، وفي قراءة ورش «ننشرها» بمعنى نحييها."]], "m": "هذا مثل آخر تتجلّى فيه ولاية الله لأوليائه: «أو كالذي مرّ على قرية وهي خاوية» فارغة من سكانها، فقال مستبعداً حياتها: كيف يحيي الله هذه القرية بعد خرابها؟ فأماته الله مائة عام ثم أحياه وسأله: كم لبثت؟ قال: يوماً أو بعض يوم، على عادة من نام ثم استيقظ. فقال: بل لبثت مائة عام، فانظر إلى طعامك وشرابك لم يتغيّر، وانظر إلى حمارك قد هلك ولم يبقَ إلا عظامه، وانظر إلى العظام كيف نجمعها ونكسوها لحماً، فإذا هو حمارك كما كان. فتجلّت قدرة الله في عدم تغيّر ما يتغير في يوم واحد، وتغيّر ما لا يتغير إلا في أعوام، وفي موت صاحبهما وحياته بعد مائة عام. وقال له ربه: فعلنا هذا لنريك قدرتنا على إحياء القرية متى أردنا، ولنجعلك آية للناس تدعوهم إلى الإيمان بالبعث. ولما لاحت أنوار ولاية الله في قلب هذا العبد قال: أعلم أن الله على كل شيء قدير.", "h": ["جواز طروء استبعاد ما يؤمن العبد بأنه حق وكائن، كما استبعد هذا المؤمن حياة القرية بعد خرابها.", "عظيم قدرة الله، فلا يعجزه شيء وهو على كل شيء قدير.", "ولاية الله للعبد المؤمن التقي تجلّت في إذهاب الظلمة التي ظهرت على قلبه، فأراه من مظاهر قدرته حتى قال: «أعلم أن الله على كل شيء قدير»."], "k": "هل استبعدتُ يوماً فرجاً أو إصلاحاً لأمرٍ خرِب؟ فأين أنا من قول المارّ بالقرية: «أعلم أن الله على كل شيء قدير»؟"}, {"lbl": "الآية ٢٦٠", "q": "وَإِذۡ قَالَ إِبۡرَٰهِـۧمُ رَبِّ أَرِنِي كَيۡفَ تُحۡيِ ٱلۡمَوۡتَىٰۖ قَالَ أَوَلَمۡ تُؤۡمِنۖ قَالَ بَلَىٰ وَلَٰكِن لِّيَطۡمَئِنَّ قَلۡبِيۖ قَالَ فَخُذۡ أَرۡبَعَةٗ مِّنَ ٱلطَّيۡرِ فَصُرۡهُنَّ إِلَيۡكَ ثُمَّ ٱجۡعَلۡ عَلَىٰ كُلِّ جَبَلٖ مِّنۡهُنَّ جُزۡءٗا ثُمَّ ٱدۡعُهُنَّ يَأۡتِينَكَ سَعۡيٗاۚ وَٱعۡلَمۡ أَنَّ ٱللَّهَ عَزِيزٌ حَكِيمٞ ﴿٢٦٠﴾", "w": [["يطمئن قلبي", "يسكن ويهدأ من التطلع والتشوّق إلى معرفة الكيفية."], ["فصُرهن إليك", "أمِلهنّ واضممهنّ إليك وقطّعهنّ أجزاء."], ["سعياً", "مشياً سريعاً وطيراناً."], ["عزيز", "غالب لا يمتنع عنه شيء أراده."], ["حكيم", "لا يخلق عبثاً، ولا يضع شيئاً في غير موضعه اللائق به."]], "m": "هذا مثل ثالث تتجلّى فيه ولاية الله لعباده المؤمنين، حتى من ظلمة التطلّع إلى معرفة كيفية شيء: سأل إبراهيم ﵇ ربه أن يريه كيف يحيي الموتى، فقال له ربه وهو أعلم به: أوَلم تؤمن؟ قال: بلى، أنا مؤمن بأنك على كل شيء قدير، ولكن أريد أن أرى صورة ذلك ليطمئن قلبي ويسكن من التشوّق إلى معرفة المجهول. فأجابه ربه لأنه وليّه، فأمره أن يأخذ أربعة من الطير فيذبحها ويقطّعها ويخلط أجزاءها، ثم يضع على كل جبل جزءاً منها، ثم يدعوها، ففعل، فاجتمعت أجزاء كل طير وجاءه يسعى، وإبراهيم ينظر ويشاهد مظاهر قدرة ربه العزيز الحكيم.", "h": ["غريزة الإنسان في حب معرفة المجهول والتطلّع إليه.", "ولاية الله لإبراهيم ﵇، إذ أراه من آياته ما اطمأن به قلبه.", "ثبوت عقيدة الحياة الثانية ببعث الخلائق أحياء للحساب والجزاء.", "زيادة الإيمان واليقين كلما نظر العبد في آيات الله الكونية، أو قرأ وتدبّر آياته القرآنية."], "k": "«ليطمئنّ قلبي»… ما الآية التي أتأمّلها اليوم في خلق الله ليزداد بها يقيني؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 37;
insert into public.tdb_cards(topic, i, body) select 37, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآية ٢٥٨", "q": "أَلَمۡ تَرَ إِلَى ٱلَّذِي حَآجَّ إِبۡرَٰهِـۧمَ فِي رَبِّهِۦٓ أَنۡ ءَاتَىٰهُ ٱللَّهُ ٱلۡمُلۡكَ إِذۡ قَالَ إِبۡرَٰهِـۧمُ رَبِّيَ ٱلَّذِي يُحۡيِۦ وَيُمِيتُ قَالَ أَنَا۠ أُحۡيِۦ وَأُمِيتُۖ قَالَ إِبۡرَٰهِـۧمُ فَإِنَّ ٱللَّهَ يَأۡتِي بِٱلشَّمۡسِ مِنَ ٱلۡمَشۡرِقِ فَأۡتِ بِهَا مِنَ ٱلۡمَغۡرِبِ فَبُهِتَ ٱلَّذِي كَفَرَۗ وَٱللَّهُ لَا يَهۡدِي ٱلۡقَوۡمَ ٱلظَّـٰلِمِينَ ﴿٢٥٨﴾", "w": [["ألم تر", "ألم ينتهِ إلى علمك يا رسولنا؟ والاستفهام للتعجب من الطاغية."], ["حاجّ", "جادل وخاصم."], ["في ربه", "في شأن ربه من وجوده وربوبيته وألوهيته."], ["آتاه الله الملك", "أعطاه الحكم والسيادة على أهل بلاده."], ["إبراهيم", "أبو الأنبياء الخليل ﵇، وكان هذا الحجاج قبل هجرته إلى الشام."], ["فبُهت الذي كفر", "انقطع عن الحجة متحيّراً مدهوشاً، وهو النمرود البابلي."]], "m": "لما ذكر الله ولايته لأوليائه، وأنه مؤيّدهم وناصرهم ومخرجهم من الظلمات إلى النور، ضرب لذلك مثلاً: ألم تر إلى الطاغية الذي أبطرته نعمة الملك فجادل إبراهيم ﵇ في ربه؟ إنه لأمر عجب! قال له إبراهيم: ربي الذي يحيي ويميت، فقال: أنا أحيي وأميت. فردّ عليه إبراهيم بحجة أخرى: إن ربي يأتي بالشمس من المشرق فأتِ بها أنت من المغرب، فاندهش وتحيّر وانقطع، وأيّد الله وليّه إبراهيم فانتصر. فهذا مثال لإخراج الله أولياءه من ظلمة الجهل إلى نور العلم.", "h": ["النعم تُبطر صاحبها إذا حُرم ولاية الله.", "نصرة الله لأوليائه وإلهامهم الحجة لخصم أعدائهم.", "إذا ظلم العبد ووالى الظلم حتى أصبح وصفاً له حُرم هداية الله فلا يهتدي أبداً.", "جواز المجادلة والمناظرة في إثبات العقيدة الصحيحة."], "k": "إذا أُعطيت قوة أو منصباً، هل يزيدني ذلك تواضعاً لله… أم يغريني بالكِبر كما أغرى النمرود؟"}, {"lbl": "الآية ٢٥٩", "q": "أَوۡ كَٱلَّذِي مَرَّ عَلَىٰ قَرۡيَةٖ وَهِيَ خَاوِيَةٌ عَلَىٰ عُرُوشِهَا قَالَ أَنَّىٰ يُحۡيِۦ هَٰذِهِ ٱللَّهُ بَعۡدَ مَوۡتِهَاۖ فَأَمَاتَهُ ٱللَّهُ مِاْئَةَ عَامٖ ثُمَّ بَعَثَهُۥۖ قَالَ كَمۡ لَبِثۡتَۖ قَالَ لَبِثۡتُ يَوۡمًا أَوۡ بَعۡضَ يَوۡمٖۖ قَالَ بَل لَّبِثۡتَ مِاْئَةَ عَامٖ فَٱنظُرۡ إِلَىٰ طَعَامِكَ وَشَرَابِكَ لَمۡ يَتَسَنَّهۡۖ وَٱنظُرۡ إِلَىٰ حِمَارِكَ وَلِنَجۡعَلَكَ ءَايَةٗ لِّلنَّاسِۖ وَٱنظُرۡ إِلَى ٱلۡعِظَامِ كَيۡفَ نُنشِزُهَا ثُمَّ نَكۡسُوهَا لَحۡمٗاۚ فَلَمَّا تَبَيَّنَ لَهُۥ قَالَ أَعۡلَمُ أَنَّ ٱللَّهَ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٞ ﴿٢٥٩﴾", "w": [["قرية", "مدينة لم يذكر الله اسمها، فلا يُبحث عنها لعدم جدوى معرفتها."], ["خاوية", "فارغة من سكانها، ساقطة عروشها على جدرانها."], ["آية", "علامة على قدرة الله على بعث الناس أحياء يوم القيامة."], ["ننشزها", "نرفعها ونجمعها لتكون حماراً كما كانت، وفي قراءة ورش «ننشرها» بمعنى نحييها."]], "m": "هذا مثل آخر تتجلّى فيه ولاية الله لأوليائه: «أو كالذي مرّ على قرية وهي خاوية» فارغة من سكانها، فقال مستبعداً حياتها: كيف يحيي الله هذه القرية بعد خرابها؟ فأماته الله مائة عام ثم أحياه وسأله: كم لبثت؟ قال: يوماً أو بعض يوم، على عادة من نام ثم استيقظ. فقال: بل لبثت مائة عام، فانظر إلى طعامك وشرابك لم يتغيّر، وانظر إلى حمارك قد هلك ولم يبقَ إلا عظامه، وانظر إلى العظام كيف نجمعها ونكسوها لحماً، فإذا هو حمارك كما كان. فتجلّت قدرة الله في عدم تغيّر ما يتغير في يوم واحد، وتغيّر ما لا يتغير إلا في أعوام، وفي موت صاحبهما وحياته بعد مائة عام. وقال له ربه: فعلنا هذا لنريك قدرتنا على إحياء القرية متى أردنا، ولنجعلك آية للناس تدعوهم إلى الإيمان بالبعث. ولما لاحت أنوار ولاية الله في قلب هذا العبد قال: أعلم أن الله على كل شيء قدير.", "h": ["جواز طروء استبعاد ما يؤمن العبد بأنه حق وكائن، كما استبعد هذا المؤمن حياة القرية بعد خرابها.", "عظيم قدرة الله، فلا يعجزه شيء وهو على كل شيء قدير.", "ولاية الله للعبد المؤمن التقي تجلّت في إذهاب الظلمة التي ظهرت على قلبه، فأراه من مظاهر قدرته حتى قال: «أعلم أن الله على كل شيء قدير»."], "k": "هل استبعدتُ يوماً فرجاً أو إصلاحاً لأمرٍ خرِب؟ فأين أنا من قول المارّ بالقرية: «أعلم أن الله على كل شيء قدير»؟"}, {"lbl": "الآية ٢٦٠", "q": "وَإِذۡ قَالَ إِبۡرَٰهِـۧمُ رَبِّ أَرِنِي كَيۡفَ تُحۡيِ ٱلۡمَوۡتَىٰۖ قَالَ أَوَلَمۡ تُؤۡمِنۖ قَالَ بَلَىٰ وَلَٰكِن لِّيَطۡمَئِنَّ قَلۡبِيۖ قَالَ فَخُذۡ أَرۡبَعَةٗ مِّنَ ٱلطَّيۡرِ فَصُرۡهُنَّ إِلَيۡكَ ثُمَّ ٱجۡعَلۡ عَلَىٰ كُلِّ جَبَلٖ مِّنۡهُنَّ جُزۡءٗا ثُمَّ ٱدۡعُهُنَّ يَأۡتِينَكَ سَعۡيٗاۚ وَٱعۡلَمۡ أَنَّ ٱللَّهَ عَزِيزٌ حَكِيمٞ ﴿٢٦٠﴾", "w": [["يطمئن قلبي", "يسكن ويهدأ من التطلع والتشوّق إلى معرفة الكيفية."], ["فصُرهن إليك", "أمِلهنّ واضممهنّ إليك وقطّعهنّ أجزاء."], ["سعياً", "مشياً سريعاً وطيراناً."], ["عزيز", "غالب لا يمتنع عنه شيء أراده."], ["حكيم", "لا يخلق عبثاً، ولا يضع شيئاً في غير موضعه اللائق به."]], "m": "هذا مثل ثالث تتجلّى فيه ولاية الله لعباده المؤمنين، حتى من ظلمة التطلّع إلى معرفة كيفية شيء: سأل إبراهيم ﵇ ربه أن يريه كيف يحيي الموتى، فقال له ربه وهو أعلم به: أوَلم تؤمن؟ قال: بلى، أنا مؤمن بأنك على كل شيء قدير، ولكن أريد أن أرى صورة ذلك ليطمئن قلبي ويسكن من التشوّق إلى معرفة المجهول. فأجابه ربه لأنه وليّه، فأمره أن يأخذ أربعة من الطير فيذبحها ويقطّعها ويخلط أجزاءها، ثم يضع على كل جبل جزءاً منها، ثم يدعوها، ففعل، فاجتمعت أجزاء كل طير وجاءه يسعى، وإبراهيم ينظر ويشاهد مظاهر قدرة ربه العزيز الحكيم.", "h": ["غريزة الإنسان في حب معرفة المجهول والتطلّع إليه.", "ولاية الله لإبراهيم ﵇، إذ أراه من آياته ما اطمأن به قلبه.", "ثبوت عقيدة الحياة الثانية ببعث الخلائق أحياء للحساب والجزاء.", "زيادة الإيمان واليقين كلما نظر العبد في آيات الله الكونية، أو قرأ وتدبّر آياته القرآنية."], "k": "«ليطمئنّ قلبي»… ما الآية التي أتأمّلها اليوم في خلق الله ليزداد بها يقيني؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (38, 2, 261, 266, 'سورة البقرة ٢٦١ – ٢٦٦', 'فضل الإنفاق في سبيل الله وما يبطله', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 38) = $j$[{"lbl": "الآيات ٢٦١ – ٢٦٣", "q": "مَّثَلُ ٱلَّذِينَ يُنفِقُونَ أَمۡوَٰلَهُمۡ فِي سَبِيلِ ٱللَّهِ كَمَثَلِ حَبَّةٍ أَنۢبَتَتۡ سَبۡعَ سَنَابِلَ فِي كُلِّ سُنۢبُلَةٖ مِّاْئَةُ حَبَّةٖۗ وَٱللَّهُ يُضَٰعِفُ لِمَن يَشَآءُۚ وَٱللَّهُ وَٰسِعٌ عَلِيمٌ ﴿٢٦١﴾ ٱلَّذِينَ يُنفِقُونَ أَمۡوَٰلَهُمۡ فِي سَبِيلِ ٱللَّهِ ثُمَّ لَا يُتۡبِعُونَ مَآ أَنفَقُواْ مَنّٗا وَلَآ أَذٗى لَّهُمۡ أَجۡرُهُمۡ عِندَ رَبِّهِمۡ وَلَا خَوۡفٌ عَلَيۡهِمۡ وَلَا هُمۡ يَحۡزَنُونَ ﴿٢٦٢﴾ ۞قَوۡلٞ مَّعۡرُوفٞ وَمَغۡفِرَةٌ خَيۡرٞ مِّن صَدَقَةٖ يَتۡبَعُهَآ أَذٗىۗ وَٱللَّهُ غَنِيٌّ حَلِيمٞ ﴿٢٦٣﴾", "w": [["مثل الذين ينفقون", "صفتهم المستحسنة العجيبة."], ["سبيل الله", "كل ما يوصل إلى مرضاة الله من الإيمان وصالح الأعمال."], ["يضاعف", "يزيد ويكثر حتى يكون الشيء أضعاف ما كان."], ["منّاً ولا أذى", "المنّ: ذكر الصدقة وتعدادها على من تُصُدّق بها عليه تفضّلاً، والأذى: التطاول عليه وإذلاله بالكلمة النابية التي تمسّ كرامته."], ["قول معروف", "كلام طيب يقال للسائل المحتاج، نحو: الله يرزقنا وإياكم، الله كريم."], ["ومغفرة", "ستر على الفقير بعدم إظهار فقره، والعفو عن سوء خلقه إن كان كذلك."], ["غني", "غنيّ غنىً ذاتياً لا يفتقر معه إلى شيء أبداً."], ["حليم", "لا يعاجل بالعقوبة، بل يعفو ويصفح."]], "m": "يخبر تعالى مرغّباً في الجهاد بالمال، لأن العُدّة أولاً، أن مثل ما ينفقه المؤمن في سبيل الله في نمائه وبركته كمثل حبة بُرّ بُذرت في أرض طيبة فأنبتت سبع سنابل، في كل سنبلة مائة حبة، فأثمرت الحبة الواحدة سبعمائة حبة؛ وهكذا الدرهم ينفقه المؤمن يضاعَف إلى سبعمائة ضعف، وقد يضاعف إلى أكثر: «والله يضاعف لمن يشاء». ثم بشّر المنفقين الذين لا يُتبعون ما أنفقوا منّاً ولا أذى بأن لا خوف عليهم فيما يستقبلون، ولا هم يحزنون على ما يتركون، وهذه هي السعادة. ثم أخبر أن الكلمة الطيبة تقال للفقير فينشرح لها صدره خير من مال يُعطاه فيُهان به ويُذلّ، وأن ستر حاله والعفو عن سوء خلقه كإلحاحه في المسألة خير من صدقة يُفضح بها، والله غني عن الخلق حليم لا يعاجل بالعقوبة.", "h": ["فضل النفقة في الجهاد، وأنها أفضل النفقات.", "فضل الصدقات وعواقبها الحميدة.", "حرمة المنّ بالصدقة.", "الرد الجميل على الفقير إذا لم يوجد ما يُعطاه، وكذا العفو عن سوء القول منه ومن غيره، خير من الصدقة يتبعها أذى."], "k": "إن لم أجد ما أعطيه للسائل… هل أُعطيه على الأقل كلمة طيبة تحفظ كرامته؟"}, {"lbl": "الآية ٢٦٤", "q": "يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تُبۡطِلُواْ صَدَقَٰتِكُم بِٱلۡمَنِّ وَٱلۡأَذَىٰ كَٱلَّذِي يُنفِقُ مَالَهُۥ رِئَآءَ ٱلنَّاسِ وَلَا يُؤۡمِنُ بِٱللَّهِ وَٱلۡيَوۡمِ ٱلۡأٓخِرِۖ فَمَثَلُهُۥ كَمَثَلِ صَفۡوَانٍ عَلَيۡهِ تُرَابٞ فَأَصَابَهُۥ وَابِلٞ فَتَرَكَهُۥ صَلۡدٗاۖ لَّا يَقۡدِرُونَ عَلَىٰ شَيۡءٖ مِّمَّا كَسَبُواْۗ وَٱللَّهُ لَا يَهۡدِي ٱلۡقَوۡمَ ٱلۡكَٰفِرِينَ ﴿٢٦٤﴾", "w": [["المنّ والأذى", "تقدّم معناهما."], ["رئاء الناس", "مراءاةً لهم ليكسب مدحهم أو يدفع ذمّهم."], ["صفوان", "حجر أملس."], ["وابل", "مطر شديد."], ["صلداً", "أملس ليس عليه شيء من التراب."], ["لا يقدرون", "يعجزون عن الانتفاع بشيء من صدقاتهم الباطلة."]], "m": "بعد أن رغّب تعالى في الصدقات ونبّه إلى ما يبطل أجرها، نادى المؤمنين ناهياً عن إبطال ثواب صدقاتهم بالمنّ والأذى، مشبّهاً حالها بحال صدقات المرائي الذي لا يؤمن بالله واليوم الآخر في بطلانها. وضرب لذلك مثلاً: حجر أملس عليه تراب، فنزل عليه مطر شديد فأزال التراب وتركه أملس ليس عليه شيء؛ فكذلك تذهب الصدقات الباطلة ولا يبقى لصاحبها منها شيء ينتفع به يوم القيامة، والله لا يهدي القوم الكافرين إلى ما يسعدهم ويكملهم.", "h": ["حرمة المنّ والأذى في الصدقات، وفسادها بهما.", "بطلان صدقة المانّ والمؤذي والمرائي بها.", "حرمة الرياء، وهو من الشرك."], "k": "قبل أن أُخبر أحداً بما أعطيت… هل أريد أجر الله، أم كلمة مدح من الناس؟"}, {"lbl": "الآيتان ٢٦٥ – ٢٦٦", "q": "وَمَثَلُ ٱلَّذِينَ يُنفِقُونَ أَمۡوَٰلَهُمُ ٱبۡتِغَآءَ مَرۡضَاتِ ٱللَّهِ وَتَثۡبِيتٗا مِّنۡ أَنفُسِهِمۡ كَمَثَلِ جَنَّةِۭ بِرَبۡوَةٍ أَصَابَهَا وَابِلٞ فَـَٔاتَتۡ أُكُلَهَا ضِعۡفَيۡنِ فَإِن لَّمۡ يُصِبۡهَا وَابِلٞ فَطَلّٞۗ وَٱللَّهُ بِمَا تَعۡمَلُونَ بَصِيرٌ ﴿٢٦٥﴾ أَيَوَدُّ أَحَدُكُمۡ أَن تَكُونَ لَهُۥ جَنَّةٞ مِّن نَّخِيلٖ وَأَعۡنَابٖ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُ لَهُۥ فِيهَا مِن كُلِّ ٱلثَّمَرَٰتِ وَأَصَابَهُ ٱلۡكِبَرُ وَلَهُۥ ذُرِّيَّةٞ ضُعَفَآءُ فَأَصَابَهَآ إِعۡصَارٞ فِيهِ نَارٞ فَٱحۡتَرَقَتۡۗ كَذَٰلِكَ يُبَيِّنُ ٱللَّهُ لَكُمُ ٱلۡأٓيَٰتِ لَعَلَّكُمۡ تَتَفَكَّرُونَ ﴿٢٦٦﴾", "w": [["المثل", "الصفة المستملحة المستغربة."], ["ابتغاء مرضاة الله", "طلباً لرضا الله."], ["وتثبيتاً من أنفسهم", "تحقيقاً وتيقّناً بمثوبة الله لهم على إنفاقهم في سبيله."], ["جنة بربوة", "بستان كثير الأشجار بمكان مرتفع."], ["ضعفين", "مضاعفاً مرتين، أو ضعفي ما يثمر غيرها."], ["الوابل", "المطر الغزير الشديد."], ["الطلّ", "المطر الخفيف."], ["إعصار", "ريح عاصف فيها سموم."]], "m": "لما ذكر الله خيبة المنفقين رياءً محذّراً منها، رغّب في النفقة التي يريد بها العبد رضا الله وثوابه، فضرب لها مثلاً: بستان بمكان مرتفع أصابه مطر غزير فأعطى ثمره ضعفي ما يعطيه غيره، فإن لم يصبه المطر الغزير كفاه الندى والمطر الخفيف لعلوّ مكانه؛ والله بما تعملون بصير، فهو وعدٌ للمخلصين بعظيم الأجر، ووعيدٌ للمانّين والمرائين بالخيبة.\nثم سأل عباده تربيةً لهم: أيحب أحدكم أن يكون له بستان من نخيل وأعناب تجري من تحته الأنهار، وقد كبرت سنّه وله ذرية صغار لا يقدرون على الكسب، فأصابت البستان ريح عاتية فيها نار فأحرقته؛ كيف يكون حاله وحال أولاده؟ هكذا الذي ينفق ماله رياءً يخسره كله يوم القيامة، في وقت هو أحوج إليه من ذلك الشيخ وأطفاله. كذلك يبيّن الله لكم الآيات لعلكم تتفكرون فتهتدوا إلى كمالكم وسعادتكم.", "h": ["استحسان ضرب الأمثال تقريباً للمعاني إلى الأذهان.", "مضاعفة أجر الصدقة الخالية من المنّ والأذى ومراءاة الناس.", "بطلان صدقات المانّ والمؤذي والمرائي، وعدم الانتفاع بشيء منها.", "وجوب التفكّر في آيات الله، لا سيما ما يحمل بيان العقائد والأحكام والآداب والأخلاق."], "k": "تخيّلتُ صاحب البستان المحترق وأولاده الصغار… فهل ما أعمله اليوم سيبقى لي يوم أحتاجه؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 38;
insert into public.tdb_cards(topic, i, body) select 38, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ٢٦١ – ٢٦٣", "q": "مَّثَلُ ٱلَّذِينَ يُنفِقُونَ أَمۡوَٰلَهُمۡ فِي سَبِيلِ ٱللَّهِ كَمَثَلِ حَبَّةٍ أَنۢبَتَتۡ سَبۡعَ سَنَابِلَ فِي كُلِّ سُنۢبُلَةٖ مِّاْئَةُ حَبَّةٖۗ وَٱللَّهُ يُضَٰعِفُ لِمَن يَشَآءُۚ وَٱللَّهُ وَٰسِعٌ عَلِيمٌ ﴿٢٦١﴾ ٱلَّذِينَ يُنفِقُونَ أَمۡوَٰلَهُمۡ فِي سَبِيلِ ٱللَّهِ ثُمَّ لَا يُتۡبِعُونَ مَآ أَنفَقُواْ مَنّٗا وَلَآ أَذٗى لَّهُمۡ أَجۡرُهُمۡ عِندَ رَبِّهِمۡ وَلَا خَوۡفٌ عَلَيۡهِمۡ وَلَا هُمۡ يَحۡزَنُونَ ﴿٢٦٢﴾ ۞قَوۡلٞ مَّعۡرُوفٞ وَمَغۡفِرَةٌ خَيۡرٞ مِّن صَدَقَةٖ يَتۡبَعُهَآ أَذٗىۗ وَٱللَّهُ غَنِيٌّ حَلِيمٞ ﴿٢٦٣﴾", "w": [["مثل الذين ينفقون", "صفتهم المستحسنة العجيبة."], ["سبيل الله", "كل ما يوصل إلى مرضاة الله من الإيمان وصالح الأعمال."], ["يضاعف", "يزيد ويكثر حتى يكون الشيء أضعاف ما كان."], ["منّاً ولا أذى", "المنّ: ذكر الصدقة وتعدادها على من تُصُدّق بها عليه تفضّلاً، والأذى: التطاول عليه وإذلاله بالكلمة النابية التي تمسّ كرامته."], ["قول معروف", "كلام طيب يقال للسائل المحتاج، نحو: الله يرزقنا وإياكم، الله كريم."], ["ومغفرة", "ستر على الفقير بعدم إظهار فقره، والعفو عن سوء خلقه إن كان كذلك."], ["غني", "غنيّ غنىً ذاتياً لا يفتقر معه إلى شيء أبداً."], ["حليم", "لا يعاجل بالعقوبة، بل يعفو ويصفح."]], "m": "يخبر تعالى مرغّباً في الجهاد بالمال، لأن العُدّة أولاً، أن مثل ما ينفقه المؤمن في سبيل الله في نمائه وبركته كمثل حبة بُرّ بُذرت في أرض طيبة فأنبتت سبع سنابل، في كل سنبلة مائة حبة، فأثمرت الحبة الواحدة سبعمائة حبة؛ وهكذا الدرهم ينفقه المؤمن يضاعَف إلى سبعمائة ضعف، وقد يضاعف إلى أكثر: «والله يضاعف لمن يشاء». ثم بشّر المنفقين الذين لا يُتبعون ما أنفقوا منّاً ولا أذى بأن لا خوف عليهم فيما يستقبلون، ولا هم يحزنون على ما يتركون، وهذه هي السعادة. ثم أخبر أن الكلمة الطيبة تقال للفقير فينشرح لها صدره خير من مال يُعطاه فيُهان به ويُذلّ، وأن ستر حاله والعفو عن سوء خلقه كإلحاحه في المسألة خير من صدقة يُفضح بها، والله غني عن الخلق حليم لا يعاجل بالعقوبة.", "h": ["فضل النفقة في الجهاد، وأنها أفضل النفقات.", "فضل الصدقات وعواقبها الحميدة.", "حرمة المنّ بالصدقة.", "الرد الجميل على الفقير إذا لم يوجد ما يُعطاه، وكذا العفو عن سوء القول منه ومن غيره، خير من الصدقة يتبعها أذى."], "k": "إن لم أجد ما أعطيه للسائل… هل أُعطيه على الأقل كلمة طيبة تحفظ كرامته؟"}, {"lbl": "الآية ٢٦٤", "q": "يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تُبۡطِلُواْ صَدَقَٰتِكُم بِٱلۡمَنِّ وَٱلۡأَذَىٰ كَٱلَّذِي يُنفِقُ مَالَهُۥ رِئَآءَ ٱلنَّاسِ وَلَا يُؤۡمِنُ بِٱللَّهِ وَٱلۡيَوۡمِ ٱلۡأٓخِرِۖ فَمَثَلُهُۥ كَمَثَلِ صَفۡوَانٍ عَلَيۡهِ تُرَابٞ فَأَصَابَهُۥ وَابِلٞ فَتَرَكَهُۥ صَلۡدٗاۖ لَّا يَقۡدِرُونَ عَلَىٰ شَيۡءٖ مِّمَّا كَسَبُواْۗ وَٱللَّهُ لَا يَهۡدِي ٱلۡقَوۡمَ ٱلۡكَٰفِرِينَ ﴿٢٦٤﴾", "w": [["المنّ والأذى", "تقدّم معناهما."], ["رئاء الناس", "مراءاةً لهم ليكسب مدحهم أو يدفع ذمّهم."], ["صفوان", "حجر أملس."], ["وابل", "مطر شديد."], ["صلداً", "أملس ليس عليه شيء من التراب."], ["لا يقدرون", "يعجزون عن الانتفاع بشيء من صدقاتهم الباطلة."]], "m": "بعد أن رغّب تعالى في الصدقات ونبّه إلى ما يبطل أجرها، نادى المؤمنين ناهياً عن إبطال ثواب صدقاتهم بالمنّ والأذى، مشبّهاً حالها بحال صدقات المرائي الذي لا يؤمن بالله واليوم الآخر في بطلانها. وضرب لذلك مثلاً: حجر أملس عليه تراب، فنزل عليه مطر شديد فأزال التراب وتركه أملس ليس عليه شيء؛ فكذلك تذهب الصدقات الباطلة ولا يبقى لصاحبها منها شيء ينتفع به يوم القيامة، والله لا يهدي القوم الكافرين إلى ما يسعدهم ويكملهم.", "h": ["حرمة المنّ والأذى في الصدقات، وفسادها بهما.", "بطلان صدقة المانّ والمؤذي والمرائي بها.", "حرمة الرياء، وهو من الشرك."], "k": "قبل أن أُخبر أحداً بما أعطيت… هل أريد أجر الله، أم كلمة مدح من الناس؟"}, {"lbl": "الآيتان ٢٦٥ – ٢٦٦", "q": "وَمَثَلُ ٱلَّذِينَ يُنفِقُونَ أَمۡوَٰلَهُمُ ٱبۡتِغَآءَ مَرۡضَاتِ ٱللَّهِ وَتَثۡبِيتٗا مِّنۡ أَنفُسِهِمۡ كَمَثَلِ جَنَّةِۭ بِرَبۡوَةٍ أَصَابَهَا وَابِلٞ فَـَٔاتَتۡ أُكُلَهَا ضِعۡفَيۡنِ فَإِن لَّمۡ يُصِبۡهَا وَابِلٞ فَطَلّٞۗ وَٱللَّهُ بِمَا تَعۡمَلُونَ بَصِيرٌ ﴿٢٦٥﴾ أَيَوَدُّ أَحَدُكُمۡ أَن تَكُونَ لَهُۥ جَنَّةٞ مِّن نَّخِيلٖ وَأَعۡنَابٖ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُ لَهُۥ فِيهَا مِن كُلِّ ٱلثَّمَرَٰتِ وَأَصَابَهُ ٱلۡكِبَرُ وَلَهُۥ ذُرِّيَّةٞ ضُعَفَآءُ فَأَصَابَهَآ إِعۡصَارٞ فِيهِ نَارٞ فَٱحۡتَرَقَتۡۗ كَذَٰلِكَ يُبَيِّنُ ٱللَّهُ لَكُمُ ٱلۡأٓيَٰتِ لَعَلَّكُمۡ تَتَفَكَّرُونَ ﴿٢٦٦﴾", "w": [["المثل", "الصفة المستملحة المستغربة."], ["ابتغاء مرضاة الله", "طلباً لرضا الله."], ["وتثبيتاً من أنفسهم", "تحقيقاً وتيقّناً بمثوبة الله لهم على إنفاقهم في سبيله."], ["جنة بربوة", "بستان كثير الأشجار بمكان مرتفع."], ["ضعفين", "مضاعفاً مرتين، أو ضعفي ما يثمر غيرها."], ["الوابل", "المطر الغزير الشديد."], ["الطلّ", "المطر الخفيف."], ["إعصار", "ريح عاصف فيها سموم."]], "m": "لما ذكر الله خيبة المنفقين رياءً محذّراً منها، رغّب في النفقة التي يريد بها العبد رضا الله وثوابه، فضرب لها مثلاً: بستان بمكان مرتفع أصابه مطر غزير فأعطى ثمره ضعفي ما يعطيه غيره، فإن لم يصبه المطر الغزير كفاه الندى والمطر الخفيف لعلوّ مكانه؛ والله بما تعملون بصير، فهو وعدٌ للمخلصين بعظيم الأجر، ووعيدٌ للمانّين والمرائين بالخيبة.\nثم سأل عباده تربيةً لهم: أيحب أحدكم أن يكون له بستان من نخيل وأعناب تجري من تحته الأنهار، وقد كبرت سنّه وله ذرية صغار لا يقدرون على الكسب، فأصابت البستان ريح عاتية فيها نار فأحرقته؛ كيف يكون حاله وحال أولاده؟ هكذا الذي ينفق ماله رياءً يخسره كله يوم القيامة، في وقت هو أحوج إليه من ذلك الشيخ وأطفاله. كذلك يبيّن الله لكم الآيات لعلكم تتفكرون فتهتدوا إلى كمالكم وسعادتكم.", "h": ["استحسان ضرب الأمثال تقريباً للمعاني إلى الأذهان.", "مضاعفة أجر الصدقة الخالية من المنّ والأذى ومراءاة الناس.", "بطلان صدقات المانّ والمؤذي والمرائي، وعدم الانتفاع بشيء منها.", "وجوب التفكّر في آيات الله، لا سيما ما يحمل بيان العقائد والأحكام والآداب والأخلاق."], "k": "تخيّلتُ صاحب البستان المحترق وأولاده الصغار… فهل ما أعمله اليوم سيبقى لي يوم أحتاجه؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (39, 2, 267, 274, 'سورة البقرة ٢٦٧ – ٢٧٤', 'طيّب النفقة، والإنفاق سرّاً وعلانية', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 39) = $j$[{"lbl": "الآيات ٢٦٧ – ٢٦٩", "q": "يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ أَنفِقُواْ مِن طَيِّبَٰتِ مَا كَسَبۡتُمۡ وَمِمَّآ أَخۡرَجۡنَا لَكُم مِّنَ ٱلۡأَرۡضِۖ وَلَا تَيَمَّمُواْ ٱلۡخَبِيثَ مِنۡهُ تُنفِقُونَ وَلَسۡتُم بِـَٔاخِذِيهِ إِلَّآ أَن تُغۡمِضُواْ فِيهِۚ وَٱعۡلَمُوٓاْ أَنَّ ٱللَّهَ غَنِيٌّ حَمِيدٌ ﴿٢٦٧﴾ ٱلشَّيۡطَٰنُ يَعِدُكُمُ ٱلۡفَقۡرَ وَيَأۡمُرُكُم بِٱلۡفَحۡشَآءِۖ وَٱللَّهُ يَعِدُكُم مَّغۡفِرَةٗ مِّنۡهُ وَفَضۡلٗاۗ وَٱللَّهُ وَٰسِعٌ عَلِيمٞ ﴿٢٦٨﴾ يُؤۡتِي ٱلۡحِكۡمَةَ مَن يَشَآءُۚ وَمَن يُؤۡتَ ٱلۡحِكۡمَةَ فَقَدۡ أُوتِيَ خَيۡرٗا كَثِيرٗاۗ وَمَا يَذَّكَّرُ إِلَّآ أُوْلُواْ ٱلۡأَلۡبَٰبِ ﴿٢٦٩﴾", "w": [["من طيبات ما كسبتم", "من جيّد أموالكم وأصلحها."], ["ومما أخرجنا لكم من الأرض", "من الحبوب وأنواع الثمار."], ["ولا تيمّموا الخبيث", "لا تقصدوا الرديء تنفقون منه."], ["إلا أن تغمضوا فيه", "إلا أن تغضّوا أبصاركم عن رداءته فتأخذوه تساهلاً منكم."], ["حميد", "محمود في الأرض والسماء، في الأولى والآخرة، لما أفاض ويفيض من النعم على خلقه."], ["يعدكم الفقر", "يخوّفكم من الفقر ليمنعكم من الإنفاق في سبيل الله."], ["ويأمركم بالفحشاء", "يدعوكم إلى ارتكاب الفواحش، ومنها البخل والشح."], ["الحكمة", "فهم أسرار الشرع، وحفظ الكتاب والسنة."], ["أولو الألباب", "أصحاب العقول الراجحة المفكرة فيما ينفعهم."]], "m": "بعد الترغيب في الإنفاق، نادى الله المؤمنين وأمرهم بإخراج زكاة أموالهم من جيّد ما يكسبون من النقدين والماشية، ومما أخرج لهم من الأرض من الحبوب والثمار، ونهاهم عن التصدق بالرديء الذي لو أُعطوه في حق لهم ما قبلوه إلا متساهلين؛ وهذا تأديب منه وتربية. وأعلمهم أنه غنيّ عنهم وعن نفقاتهم، وإنما أمرهم بها لإكمالهم وإسعادهم، وأنه حميد بما له من إنعام على خلقه.\nثم حذّرهم من الشيطان: يخوّفهم الفقر حتى لا يزكّوا ولا يتصدقوا، ويأمرهم بالفحشاء فينفقون في الشر ويبخلون عن الخير؛ أما الله فيعدهم بالإنفاق مغفرةً لذنوبهم، لأن الصدقة تكفّر الخطيئة، وفضلاً وهو الرزق الواسع الحسن، فليستجيبوا لنداء ربهم ويُعرضوا عن نداء عدوهم.\nثم رغّب في العلم النافع الذي يحمل على العمل الصالح، وهو علم الكتاب والسنة حفظاً وفهماً وفقهاً: فهو يؤتي الحكمة من يشاء ممن طلبها وسأل الله أن يعلّمه، ومن أوتيها فقد أوتي خيراً كثيراً، فليطلب العاقل الحكمة قبل طلب الدنيا، «وما يذّكّر إلا أولو الألباب».", "h": ["وجوب الزكاة في الذهب والفضة وما يقوم مقامهما من العُملة، وفي الإبل والبقر والغنم، بشرط الحول وبلوغ النصاب.", "وجوب الزكاة في الحبوب والثمار إذا بلغت نصاباً، وكذا في المعادن؛ إذ يشملها لفظ الخارج من الأرض.", "قبح الإنفاق من الرديء وترك الجيد.", "التحذير من الشيطان، ووجوب مجاهدته بالإعراض عن وساوسه ومخالفة أوامره.", "إجابة نداء الله والعمل بإرشاده.", "فضل العلم على المال."], "k": "حين أُخرج صدقة… هل أختار مما أحبّ، أم مما استغنيت عنه وما كنت لأقبله لو أُعطيته؟"}, {"lbl": "الآيتان ٢٧٠ – ٢٧١", "q": "وَمَآ أَنفَقۡتُم مِّن نَّفَقَةٍ أَوۡ نَذَرۡتُم مِّن نَّذۡرٖ فَإِنَّ ٱللَّهَ يَعۡلَمُهُۥۗ وَمَا لِلظَّـٰلِمِينَ مِنۡ أَنصَارٍ ﴿٢٧٠﴾ إِن تُبۡدُواْ ٱلصَّدَقَٰتِ فَنِعِمَّا هِيَۖ وَإِن تُخۡفُوهَا وَتُؤۡتُوهَا ٱلۡفُقَرَآءَ فَهُوَ خَيۡرٞ لَّكُمۡۚ وَيُكَفِّرُ عَنكُم مِّن سَيِّـَٔاتِكُمۡۗ وَٱللَّهُ بِمَا تَعۡمَلُونَ خَبِيرٞ ﴿٢٧١﴾", "w": [["من نفقة", "قليلة أو كثيرة، من الجيد أو الرديء."], ["من نذر", "النذر: التزام المؤمن بما لم يُلزمه به الشرع، كأن يقول: لله عليّ أن أتصدق أو أصوم شهراً، أو: إن حصل لي كذا فعلت كذا من الطاعات."], ["إن تُبدوا الصدقات", "إن تُظهروها."], ["فنعمّا هي", "فنِعمت تلك الصدقة التي أظهرتموها ليُقتدى بكم فيها."], ["ويكفّر عنكم من سيئاتكم", "يسترها ولا يطالب بها، و«من» للتبعيض؛ إذ حقوق العباد لا تكفّرها الصدقة."]], "m": "أخبر تعالى أنه يعلم ما ينفقه عباده وما ينذرونه: فما كان مبتغىً به وجهه ومن جيّد المال كفّر به السيئات ورفع به الدرجات، وما كان رديئاً أو نذراً لغير الله فأهله ظالمون، يُحرمون أجره ولا يجدون من يثيبهم عليه، «وما للظالمين من أنصار».\nثم أعلم المؤمنين أن ما ينفقونه لوجهه من طيّب أموالهم علانية مال رابح ونفقة مقبولة، إلا أن ما يكون منها سرّاً ويوضع في أيدي الفقراء خير لصاحبه؛ لبعده عن شائبة الرياء، ولإكرام الفقراء وعدم تعريضهم لمذلّة التصدق عليهم، وأنه يكفّر عنهم بصدقاتهم سيئاتهم، وهو خبير بأعمالهم، فاطمأنوا إلى أجورها.", "h": ["الترغيب في الصدقات ولو قلّت، والتحذير من الرياء فيها، ومن إخراجها من رديء الأموال.", "جواز إظهار الصدقة عند سلامتها من الرياء.", "فضل صدقة السر وعظم أجرها."], "k": "صدقة لا يعلمها أحد غير الله… متى كانت آخر مرة فعلتها؟"}, {"lbl": "الآيات ٢٧٢ – ٢٧٤", "q": "۞لَّيۡسَ عَلَيۡكَ هُدَىٰهُمۡ وَلَٰكِنَّ ٱللَّهَ يَهۡدِي مَن يَشَآءُۗ وَمَا تُنفِقُواْ مِنۡ خَيۡرٖ فَلِأَنفُسِكُمۡۚ وَمَا تُنفِقُونَ إِلَّا ٱبۡتِغَآءَ وَجۡهِ ٱللَّهِۚ وَمَا تُنفِقُواْ مِنۡ خَيۡرٖ يُوَفَّ إِلَيۡكُمۡ وَأَنتُمۡ لَا تُظۡلَمُونَ ﴿٢٧٢﴾ لِلۡفُقَرَآءِ ٱلَّذِينَ أُحۡصِرُواْ فِي سَبِيلِ ٱللَّهِ لَا يَسۡتَطِيعُونَ ضَرۡبٗا فِي ٱلۡأَرۡضِ يَحۡسَبُهُمُ ٱلۡجَاهِلُ أَغۡنِيَآءَ مِنَ ٱلتَّعَفُّفِ تَعۡرِفُهُم بِسِيمَٰهُمۡ لَا يَسۡـَٔلُونَ ٱلنَّاسَ إِلۡحَافٗاۗ وَمَا تُنفِقُواْ مِنۡ خَيۡرٖ فَإِنَّ ٱللَّهَ بِهِۦ عَلِيمٌ ﴿٢٧٣﴾ ٱلَّذِينَ يُنفِقُونَ أَمۡوَٰلَهُم بِٱلَّيۡلِ وَٱلنَّهَارِ سِرّٗا وَعَلَانِيَةٗ فَلَهُمۡ أَجۡرُهُمۡ عِندَ رَبِّهِمۡ وَلَا خَوۡفٌ عَلَيۡهِمۡ وَلَا هُمۡ يَحۡزَنُونَ ﴿٢٧٤﴾", "w": [["هداهم", "هدايتهم إلى الإيمان وصالح الأعمال."], ["من خير", "من مال."], ["فلأنفسكم", "ثوابه العاجل بالبركة وحسن الذكر، والآجل يوم القيامة، عائد على أنفسكم."], ["يُوَفَّ إليكم", "يُردّ إليكم أجره كاملاً لا ينقص منه شيء."], ["أُحصروا", "حُبسوا ومُنعوا من التصرف؛ لأنهم هاجروا من بلادهم."], ["ضرباً في الأرض", "سيراً فيها لطلب الرزق بالتجارة وغيرها؛ لحصار العدو لهم."], ["بسيماهم", "بعلامات حاجتهم من رثاثة الثياب وصفرة الوجه."], ["من التعفف", "من ترك سؤال الناس والكفّ عنه."], ["إلحافاً", "إلحاحاً، وهو ملازمة السائل من يسأله حتى يعطيه."]], "m": "لما أمر الله بالصدقات وسألها غيرُ المؤمنين من الكفار واليهود، تحرّج الرسول ﷺ والمؤمنون من التصدق عليهم، فأذهب الله عنهم هذا الحرج وأذن بالتصدق على غير المؤمنين، والمراد صدقة التطوع لا الزكاة: «ليس عليك هداهم»؛ فإنما عليك بيان الطريق وقد فعلت، ولو شاء الله لهداهم. وما تنفقوا من مال على مؤمن أو كافر تريدون به وجه الله تُثابوا عليه، ويوفَّ إليكم أجره كاملاً ولا تُظلمون.\nثم بيّن أفضل جهة يُنفق فيها المال: فقراء المهاجرين الذين أُخرجوا من ديارهم وأموالهم وحُبسوا في المدينة بجوار رسول الله ﷺ لا يستطيعون سفراً للتجارة ولا للعمل، يحسبهم الجاهل بحالهم أغنياء لعفّتهم وشرف نفوسهم، تعرفهم بعلامات حاجتهم، لا يسألون الناس فضلاً عن أن يُلحّوا. ثم ختم بأعظم بشرى للمنفقين في كل أحوالهم، بالليل والنهار، سرّاً وعلانية: أن أجرهم مدّخر عند ربهم، ولا خوف عليهم ولا هم يحزنون في الدنيا والبرزخ والآخرة.", "h": ["جواز التصدق على الكافر المحتاج بصدقة التطوع لا الزكاة؛ فإنها حق المؤمنين.", "ثواب الصدقة عائد على المتصدق لا على المتصدَّق عليه، فلا يضر أن يكون كافراً.", "وجوب الإخلاص في الصدقة، بأن يُراد بها وجه الله لا غير.", "تفاضل أجر الصدقة بحسب فضل المتصدَّق عليه وحاجته.", "فضيلة التعفف، وهو ترك السؤال مع الاحتياج، وذم الإلحاح في الطلب من غير الله؛ أما الله فيحب الملحّين في دعائه.", "جواز التصدق بالليل والنهار وفي السر والعلن، إذ الكل يثيب الله عليه ما دام قد أريد به وجهه.", "بشرى الله للمؤمنين المنفقين بادّخار أجرهم عنده، ونفي الخوف والحزن عنهم."], "k": "«يحسبهم الجاهل أغنياء من التعفف»… هل حولي من يستر حاجته وأنا لا أنتبه له؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 39;
insert into public.tdb_cards(topic, i, body) select 39, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ٢٦٧ – ٢٦٩", "q": "يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ أَنفِقُواْ مِن طَيِّبَٰتِ مَا كَسَبۡتُمۡ وَمِمَّآ أَخۡرَجۡنَا لَكُم مِّنَ ٱلۡأَرۡضِۖ وَلَا تَيَمَّمُواْ ٱلۡخَبِيثَ مِنۡهُ تُنفِقُونَ وَلَسۡتُم بِـَٔاخِذِيهِ إِلَّآ أَن تُغۡمِضُواْ فِيهِۚ وَٱعۡلَمُوٓاْ أَنَّ ٱللَّهَ غَنِيٌّ حَمِيدٌ ﴿٢٦٧﴾ ٱلشَّيۡطَٰنُ يَعِدُكُمُ ٱلۡفَقۡرَ وَيَأۡمُرُكُم بِٱلۡفَحۡشَآءِۖ وَٱللَّهُ يَعِدُكُم مَّغۡفِرَةٗ مِّنۡهُ وَفَضۡلٗاۗ وَٱللَّهُ وَٰسِعٌ عَلِيمٞ ﴿٢٦٨﴾ يُؤۡتِي ٱلۡحِكۡمَةَ مَن يَشَآءُۚ وَمَن يُؤۡتَ ٱلۡحِكۡمَةَ فَقَدۡ أُوتِيَ خَيۡرٗا كَثِيرٗاۗ وَمَا يَذَّكَّرُ إِلَّآ أُوْلُواْ ٱلۡأَلۡبَٰبِ ﴿٢٦٩﴾", "w": [["من طيبات ما كسبتم", "من جيّد أموالكم وأصلحها."], ["ومما أخرجنا لكم من الأرض", "من الحبوب وأنواع الثمار."], ["ولا تيمّموا الخبيث", "لا تقصدوا الرديء تنفقون منه."], ["إلا أن تغمضوا فيه", "إلا أن تغضّوا أبصاركم عن رداءته فتأخذوه تساهلاً منكم."], ["حميد", "محمود في الأرض والسماء، في الأولى والآخرة، لما أفاض ويفيض من النعم على خلقه."], ["يعدكم الفقر", "يخوّفكم من الفقر ليمنعكم من الإنفاق في سبيل الله."], ["ويأمركم بالفحشاء", "يدعوكم إلى ارتكاب الفواحش، ومنها البخل والشح."], ["الحكمة", "فهم أسرار الشرع، وحفظ الكتاب والسنة."], ["أولو الألباب", "أصحاب العقول الراجحة المفكرة فيما ينفعهم."]], "m": "بعد الترغيب في الإنفاق، نادى الله المؤمنين وأمرهم بإخراج زكاة أموالهم من جيّد ما يكسبون من النقدين والماشية، ومما أخرج لهم من الأرض من الحبوب والثمار، ونهاهم عن التصدق بالرديء الذي لو أُعطوه في حق لهم ما قبلوه إلا متساهلين؛ وهذا تأديب منه وتربية. وأعلمهم أنه غنيّ عنهم وعن نفقاتهم، وإنما أمرهم بها لإكمالهم وإسعادهم، وأنه حميد بما له من إنعام على خلقه.\nثم حذّرهم من الشيطان: يخوّفهم الفقر حتى لا يزكّوا ولا يتصدقوا، ويأمرهم بالفحشاء فينفقون في الشر ويبخلون عن الخير؛ أما الله فيعدهم بالإنفاق مغفرةً لذنوبهم، لأن الصدقة تكفّر الخطيئة، وفضلاً وهو الرزق الواسع الحسن، فليستجيبوا لنداء ربهم ويُعرضوا عن نداء عدوهم.\nثم رغّب في العلم النافع الذي يحمل على العمل الصالح، وهو علم الكتاب والسنة حفظاً وفهماً وفقهاً: فهو يؤتي الحكمة من يشاء ممن طلبها وسأل الله أن يعلّمه، ومن أوتيها فقد أوتي خيراً كثيراً، فليطلب العاقل الحكمة قبل طلب الدنيا، «وما يذّكّر إلا أولو الألباب».", "h": ["وجوب الزكاة في الذهب والفضة وما يقوم مقامهما من العُملة، وفي الإبل والبقر والغنم، بشرط الحول وبلوغ النصاب.", "وجوب الزكاة في الحبوب والثمار إذا بلغت نصاباً، وكذا في المعادن؛ إذ يشملها لفظ الخارج من الأرض.", "قبح الإنفاق من الرديء وترك الجيد.", "التحذير من الشيطان، ووجوب مجاهدته بالإعراض عن وساوسه ومخالفة أوامره.", "إجابة نداء الله والعمل بإرشاده.", "فضل العلم على المال."], "k": "حين أُخرج صدقة… هل أختار مما أحبّ، أم مما استغنيت عنه وما كنت لأقبله لو أُعطيته؟"}, {"lbl": "الآيتان ٢٧٠ – ٢٧١", "q": "وَمَآ أَنفَقۡتُم مِّن نَّفَقَةٍ أَوۡ نَذَرۡتُم مِّن نَّذۡرٖ فَإِنَّ ٱللَّهَ يَعۡلَمُهُۥۗ وَمَا لِلظَّـٰلِمِينَ مِنۡ أَنصَارٍ ﴿٢٧٠﴾ إِن تُبۡدُواْ ٱلصَّدَقَٰتِ فَنِعِمَّا هِيَۖ وَإِن تُخۡفُوهَا وَتُؤۡتُوهَا ٱلۡفُقَرَآءَ فَهُوَ خَيۡرٞ لَّكُمۡۚ وَيُكَفِّرُ عَنكُم مِّن سَيِّـَٔاتِكُمۡۗ وَٱللَّهُ بِمَا تَعۡمَلُونَ خَبِيرٞ ﴿٢٧١﴾", "w": [["من نفقة", "قليلة أو كثيرة، من الجيد أو الرديء."], ["من نذر", "النذر: التزام المؤمن بما لم يُلزمه به الشرع، كأن يقول: لله عليّ أن أتصدق أو أصوم شهراً، أو: إن حصل لي كذا فعلت كذا من الطاعات."], ["إن تُبدوا الصدقات", "إن تُظهروها."], ["فنعمّا هي", "فنِعمت تلك الصدقة التي أظهرتموها ليُقتدى بكم فيها."], ["ويكفّر عنكم من سيئاتكم", "يسترها ولا يطالب بها، و«من» للتبعيض؛ إذ حقوق العباد لا تكفّرها الصدقة."]], "m": "أخبر تعالى أنه يعلم ما ينفقه عباده وما ينذرونه: فما كان مبتغىً به وجهه ومن جيّد المال كفّر به السيئات ورفع به الدرجات، وما كان رديئاً أو نذراً لغير الله فأهله ظالمون، يُحرمون أجره ولا يجدون من يثيبهم عليه، «وما للظالمين من أنصار».\nثم أعلم المؤمنين أن ما ينفقونه لوجهه من طيّب أموالهم علانية مال رابح ونفقة مقبولة، إلا أن ما يكون منها سرّاً ويوضع في أيدي الفقراء خير لصاحبه؛ لبعده عن شائبة الرياء، ولإكرام الفقراء وعدم تعريضهم لمذلّة التصدق عليهم، وأنه يكفّر عنهم بصدقاتهم سيئاتهم، وهو خبير بأعمالهم، فاطمأنوا إلى أجورها.", "h": ["الترغيب في الصدقات ولو قلّت، والتحذير من الرياء فيها، ومن إخراجها من رديء الأموال.", "جواز إظهار الصدقة عند سلامتها من الرياء.", "فضل صدقة السر وعظم أجرها."], "k": "صدقة لا يعلمها أحد غير الله… متى كانت آخر مرة فعلتها؟"}, {"lbl": "الآيات ٢٧٢ – ٢٧٤", "q": "۞لَّيۡسَ عَلَيۡكَ هُدَىٰهُمۡ وَلَٰكِنَّ ٱللَّهَ يَهۡدِي مَن يَشَآءُۗ وَمَا تُنفِقُواْ مِنۡ خَيۡرٖ فَلِأَنفُسِكُمۡۚ وَمَا تُنفِقُونَ إِلَّا ٱبۡتِغَآءَ وَجۡهِ ٱللَّهِۚ وَمَا تُنفِقُواْ مِنۡ خَيۡرٖ يُوَفَّ إِلَيۡكُمۡ وَأَنتُمۡ لَا تُظۡلَمُونَ ﴿٢٧٢﴾ لِلۡفُقَرَآءِ ٱلَّذِينَ أُحۡصِرُواْ فِي سَبِيلِ ٱللَّهِ لَا يَسۡتَطِيعُونَ ضَرۡبٗا فِي ٱلۡأَرۡضِ يَحۡسَبُهُمُ ٱلۡجَاهِلُ أَغۡنِيَآءَ مِنَ ٱلتَّعَفُّفِ تَعۡرِفُهُم بِسِيمَٰهُمۡ لَا يَسۡـَٔلُونَ ٱلنَّاسَ إِلۡحَافٗاۗ وَمَا تُنفِقُواْ مِنۡ خَيۡرٖ فَإِنَّ ٱللَّهَ بِهِۦ عَلِيمٌ ﴿٢٧٣﴾ ٱلَّذِينَ يُنفِقُونَ أَمۡوَٰلَهُم بِٱلَّيۡلِ وَٱلنَّهَارِ سِرّٗا وَعَلَانِيَةٗ فَلَهُمۡ أَجۡرُهُمۡ عِندَ رَبِّهِمۡ وَلَا خَوۡفٌ عَلَيۡهِمۡ وَلَا هُمۡ يَحۡزَنُونَ ﴿٢٧٤﴾", "w": [["هداهم", "هدايتهم إلى الإيمان وصالح الأعمال."], ["من خير", "من مال."], ["فلأنفسكم", "ثوابه العاجل بالبركة وحسن الذكر، والآجل يوم القيامة، عائد على أنفسكم."], ["يُوَفَّ إليكم", "يُردّ إليكم أجره كاملاً لا ينقص منه شيء."], ["أُحصروا", "حُبسوا ومُنعوا من التصرف؛ لأنهم هاجروا من بلادهم."], ["ضرباً في الأرض", "سيراً فيها لطلب الرزق بالتجارة وغيرها؛ لحصار العدو لهم."], ["بسيماهم", "بعلامات حاجتهم من رثاثة الثياب وصفرة الوجه."], ["من التعفف", "من ترك سؤال الناس والكفّ عنه."], ["إلحافاً", "إلحاحاً، وهو ملازمة السائل من يسأله حتى يعطيه."]], "m": "لما أمر الله بالصدقات وسألها غيرُ المؤمنين من الكفار واليهود، تحرّج الرسول ﷺ والمؤمنون من التصدق عليهم، فأذهب الله عنهم هذا الحرج وأذن بالتصدق على غير المؤمنين، والمراد صدقة التطوع لا الزكاة: «ليس عليك هداهم»؛ فإنما عليك بيان الطريق وقد فعلت، ولو شاء الله لهداهم. وما تنفقوا من مال على مؤمن أو كافر تريدون به وجه الله تُثابوا عليه، ويوفَّ إليكم أجره كاملاً ولا تُظلمون.\nثم بيّن أفضل جهة يُنفق فيها المال: فقراء المهاجرين الذين أُخرجوا من ديارهم وأموالهم وحُبسوا في المدينة بجوار رسول الله ﷺ لا يستطيعون سفراً للتجارة ولا للعمل، يحسبهم الجاهل بحالهم أغنياء لعفّتهم وشرف نفوسهم، تعرفهم بعلامات حاجتهم، لا يسألون الناس فضلاً عن أن يُلحّوا. ثم ختم بأعظم بشرى للمنفقين في كل أحوالهم، بالليل والنهار، سرّاً وعلانية: أن أجرهم مدّخر عند ربهم، ولا خوف عليهم ولا هم يحزنون في الدنيا والبرزخ والآخرة.", "h": ["جواز التصدق على الكافر المحتاج بصدقة التطوع لا الزكاة؛ فإنها حق المؤمنين.", "ثواب الصدقة عائد على المتصدق لا على المتصدَّق عليه، فلا يضر أن يكون كافراً.", "وجوب الإخلاص في الصدقة، بأن يُراد بها وجه الله لا غير.", "تفاضل أجر الصدقة بحسب فضل المتصدَّق عليه وحاجته.", "فضيلة التعفف، وهو ترك السؤال مع الاحتياج، وذم الإلحاح في الطلب من غير الله؛ أما الله فيحب الملحّين في دعائه.", "جواز التصدق بالليل والنهار وفي السر والعلن، إذ الكل يثيب الله عليه ما دام قد أريد به وجهه.", "بشرى الله للمؤمنين المنفقين بادّخار أجرهم عنده، ونفي الخوف والحزن عنهم."], "k": "«يحسبهم الجاهل أغنياء من التعفف»… هل حولي من يستر حاجته وأنا لا أنتبه له؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (40, 2, 275, 281, 'سورة البقرة ٢٧٥ – ٢٨١', 'تحريم الربا', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 40) = $j$[{"lbl": "الآيات ٢٧٥ – ٢٧٧", "q": "ٱلَّذِينَ يَأۡكُلُونَ ٱلرِّبَوٰاْ لَا يَقُومُونَ إِلَّا كَمَا يَقُومُ ٱلَّذِي يَتَخَبَّطُهُ ٱلشَّيۡطَٰنُ مِنَ ٱلۡمَسِّۚ ذَٰلِكَ بِأَنَّهُمۡ قَالُوٓاْ إِنَّمَا ٱلۡبَيۡعُ مِثۡلُ ٱلرِّبَوٰاْۗ وَأَحَلَّ ٱللَّهُ ٱلۡبَيۡعَ وَحَرَّمَ ٱلرِّبَوٰاْۚ فَمَن جَآءَهُۥ مَوۡعِظَةٞ مِّن رَّبِّهِۦ فَٱنتَهَىٰ فَلَهُۥ مَا سَلَفَ وَأَمۡرُهُۥٓ إِلَى ٱللَّهِۖ وَمَنۡ عَادَ فَأُوْلَـٰٓئِكَ أَصۡحَٰبُ ٱلنَّارِۖ هُمۡ فِيهَا خَٰلِدُونَ ﴿٢٧٥﴾ يَمۡحَقُ ٱللَّهُ ٱلرِّبَوٰاْ وَيُرۡبِي ٱلصَّدَقَٰتِۗ وَٱللَّهُ لَا يُحِبُّ كُلَّ كَفَّارٍ أَثِيمٍ ﴿٢٧٦﴾ إِنَّ ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّـٰلِحَٰتِ وَأَقَامُواْ ٱلصَّلَوٰةَ وَءَاتَوُاْ ٱلزَّكَوٰةَ لَهُمۡ أَجۡرُهُمۡ عِندَ رَبِّهِمۡ وَلَا خَوۡفٌ عَلَيۡهِمۡ وَلَا هُمۡ يَحۡزَنُونَ ﴿٢٧٧﴾", "w": [["يأكلون الربا", "يأخذونه ويتصرفون فيه بالأكل وغيره. والربا هنا ربا النسيئة: أن يكون لك على المرء دَين، فإذا حلّ أجله ولم يقدر على سداده قلت: أخّر وزِد. وهذا ربا الجاهلية، والعمل به اليوم في البنوك الربوية. والربا حرام بالكتاب والسنة والإجماع، ربا فضل كان أو ربا نسيئة."], ["لا يقومون", "من قبورهم يوم القيامة."], ["يتخبّطه الشيطان", "يضربه الشيطان ضرباً غير منتظم."], ["من المسّ", "من الجنون."], ["موعظة", "أمر أو نهي بترك الربا."], ["فله ما سلف", "ليس عليه أن يردّ الأموال التي سبقت توبته."], ["يمحق الله الربا", "يُذهبه شيئاً فشيئاً حتى لا يبقى منه شيء، كمحاق القمر آخر الشهر."], ["ويُربي الصدقات", "يبارك في المال الذي أُخرجت منه، ويضاعف أجرها أضعافاً."], ["كفّار أثيم", "الكفّار: شديد الكفر بكل حق وخير، والأثيم: المنغمس في الذنوب لا يترك كبيرة ولا صغيرة إلا ارتكبها."]], "m": "لما حثّ الله على الصدقات ووعد عليها بعظيم الأجر، ذكر المرابين الذين يضاعفون مكاسبهم بالربا فيسدّون طرق البر، فذكر حالهم عند القيام من قبورهم: يقومون ويسقطون، حالهم حال من يُصرع في الدنيا بمسّ الجنون، علامة يُعرفون بها يوم القيامة. وسبب ذلك أنهم ردّوا حكم الله بتحريم الربا وقالوا: إنما البيع مثل الربا، فردّ عليهم: «وأحلّ الله البيع وحرّم الربا»، فما دام قد حرّمه فلا معنى للاعتراض؛ ونسوا أن الزيادة في البيع في قيمة سلعة تغلو وترخص، أما زيادة الربا فزيادة في الأجل فقط. ثم بيّن سبيل النجاة: فمن جاءه نهي ربه فانتهى فله ما سلف قبل التوبة، وأمره إلى الله، ومن عاد فأولئك أصحاب النار هم فيها خالدون. وأخبر أنه بعدله يمحق الربا وبفضله يُربي الصدقات، وأنه لا يحب كل كفّار أثيم.\nثم بشّر من آمن وعمل صالحاً وأقام الصلاة وآتى الزكاة بأن أجره وافٍ عند ربه يتسلّمه يوم القيامة، ولا خوف عليه ولا هو يحزن في الدنيا ولا في الآخرة.", "h": ["بيان عقوبة أكلة الربا يوم القيامة؛ لاستباحتهم الربا وعدم التوبة منه.", "حرمة الربا وكل مال حرام؛ لما جاء في الآية من الوعيد الشديد.", "صفة الحب لله تعالى، فهو يحب أولياءه أهل الإيمان والطاعة، ويكره أعداءه أهل الكفر والمعاصي من أكل الربا وغيره من الكبائر.", "حِلّ البيع إن تمّ على شروطه المبيّنة في كتب الفقه.", "من تاب من الربا قُبلت توبته، ويحلّ له ما أفاده منه قبل التوبة بشرط يأتي في الآيات بعدها.", "وعيد الله بمحق الربا، ووعده بإرباء الصدقة.", "بشرى الله لأهل الإيمان والعمل الصالح مع إقامة الصلاة وإيتاء الزكاة."], "k": "«يمحق الله الربا ويُربي الصدقات»… أيّهما أحرص عليه: ما يزيد في رصيدي، أم ما يبارك الله فيه؟"}, {"lbl": "الآيات ٢٧٨ – ٢٨١", "q": "يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ ٱتَّقُواْ ٱللَّهَ وَذَرُواْ مَا بَقِيَ مِنَ ٱلرِّبَوٰٓاْ إِن كُنتُم مُّؤۡمِنِينَ ﴿٢٧٨﴾ فَإِن لَّمۡ تَفۡعَلُواْ فَأۡذَنُواْ بِحَرۡبٖ مِّنَ ٱللَّهِ وَرَسُولِهِۦۖ وَإِن تُبۡتُمۡ فَلَكُمۡ رُءُوسُ أَمۡوَٰلِكُمۡ لَا تَظۡلِمُونَ وَلَا تُظۡلَمُونَ ﴿٢٧٩﴾ وَإِن كَانَ ذُو عُسۡرَةٖ فَنَظِرَةٌ إِلَىٰ مَيۡسَرَةٖۚ وَأَن تَصَدَّقُواْ خَيۡرٞ لَّكُمۡ إِن كُنتُمۡ تَعۡلَمُونَ ﴿٢٨٠﴾ وَٱتَّقُواْ يَوۡمٗا تُرۡجَعُونَ فِيهِ إِلَى ٱللَّهِۖ ثُمَّ تُوَفَّىٰ كُلُّ نَفۡسٖ مَّا كَسَبَتۡ وَهُمۡ لَا يُظۡلَمُونَ ﴿٢٨١﴾", "w": [["اتقوا الله", "خافوا عقابه بأن تجعلوا طاعته وقاية تقيكم غضبه."], ["وذروا ما بقي من الربا", "اتركوا ما بقي عندكم من المعاملات الربوية."], ["فأذنوا بحرب", "فاعلموا بحرب من الله ورسوله، ولا ينفعكم فيها سلاح، فإنكم المهزومون الهالكون."], ["فلكم رؤوس أموالكم", "بعد التوبة ليس لكم إلا رأس المال الذي عند المدين، فخذوه واتركوا زيادة الربا."], ["ذو عُسرة", "ذو شدّة وضائقة مالية."], ["فنظرة إلى ميسرة", "انتظار للمدين حتى ييسّر الله عليه فيعطيكم رأس مالكم."], ["وأن تصدّقوا", "وأن تتصدقوا على المعسر بترك ما لكم عليه، فذلك خير لكم."]], "m": "بمناسبة ذكر عقوبة أكلة الربا، نادى الله المؤمنين آمراً إياهم بتقواه، وبترك ما بقي عند بعضهم من المعاملات الربوية، مذكّراً بإيمانهم؛ إذ من شأن المؤمن أن يستجيب لنداء ربه. ثم هدّد المتباطئين: فإن لم تفعلوا فاعلموا بحرب ضروس من الله ورسوله. ثم بيّن طريق التوبة: إن تبتم فلكم رؤوس أموالكم لا غير؛ لا تَظلمون بأخذ زيادة، ولا تُظلمون بنقص من رأس المال. وإن كان المدين معسراً فالواجب انتظاره إلى ميسرته، وخير لكم أن تتصدقوا بالتنازل عن ديونكم كلها، تطهيراً لأموالكم التي لامسها الربا وتزكية لأنفسكم من آثاره. ثم ذكّر عباده بيوم القيامة وما فيه من حساب دقيق تُجزى فيه كل نفس ما كسبت وهم لا يُظلمون، وهذه الآية آخر ما نزل من السماء على رسول الله ﷺ.", "h": ["وجوب التوبة من الربا ومن كل المعاصي.", "المُصرّ على المعاملات الربوية يجب على الحاكم أن يحاربه بالضرب على يديه حتى يترك الربا.", "من تاب من الربا لا يُظلم بالأخذ من رأس ماله، بل يُعطاه كاملاً، إلا أن يتصدق بالتنازل عن ديونه الربوية فذلك خير له.", "وجوب ذكر الدار الآخرة والاستعداد لها بالإيمان والعمل الصالح وترك الربا والمعاصي."], "k": "«واتقوا يوماً تُرجعون فيه إلى الله»… آخر ما نزل من القرآن؛ فماذا أُعِدّ لذلك اليوم من الآن؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 40;
insert into public.tdb_cards(topic, i, body) select 40, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ٢٧٥ – ٢٧٧", "q": "ٱلَّذِينَ يَأۡكُلُونَ ٱلرِّبَوٰاْ لَا يَقُومُونَ إِلَّا كَمَا يَقُومُ ٱلَّذِي يَتَخَبَّطُهُ ٱلشَّيۡطَٰنُ مِنَ ٱلۡمَسِّۚ ذَٰلِكَ بِأَنَّهُمۡ قَالُوٓاْ إِنَّمَا ٱلۡبَيۡعُ مِثۡلُ ٱلرِّبَوٰاْۗ وَأَحَلَّ ٱللَّهُ ٱلۡبَيۡعَ وَحَرَّمَ ٱلرِّبَوٰاْۚ فَمَن جَآءَهُۥ مَوۡعِظَةٞ مِّن رَّبِّهِۦ فَٱنتَهَىٰ فَلَهُۥ مَا سَلَفَ وَأَمۡرُهُۥٓ إِلَى ٱللَّهِۖ وَمَنۡ عَادَ فَأُوْلَـٰٓئِكَ أَصۡحَٰبُ ٱلنَّارِۖ هُمۡ فِيهَا خَٰلِدُونَ ﴿٢٧٥﴾ يَمۡحَقُ ٱللَّهُ ٱلرِّبَوٰاْ وَيُرۡبِي ٱلصَّدَقَٰتِۗ وَٱللَّهُ لَا يُحِبُّ كُلَّ كَفَّارٍ أَثِيمٍ ﴿٢٧٦﴾ إِنَّ ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّـٰلِحَٰتِ وَأَقَامُواْ ٱلصَّلَوٰةَ وَءَاتَوُاْ ٱلزَّكَوٰةَ لَهُمۡ أَجۡرُهُمۡ عِندَ رَبِّهِمۡ وَلَا خَوۡفٌ عَلَيۡهِمۡ وَلَا هُمۡ يَحۡزَنُونَ ﴿٢٧٧﴾", "w": [["يأكلون الربا", "يأخذونه ويتصرفون فيه بالأكل وغيره. والربا هنا ربا النسيئة: أن يكون لك على المرء دَين، فإذا حلّ أجله ولم يقدر على سداده قلت: أخّر وزِد. وهذا ربا الجاهلية، والعمل به اليوم في البنوك الربوية. والربا حرام بالكتاب والسنة والإجماع، ربا فضل كان أو ربا نسيئة."], ["لا يقومون", "من قبورهم يوم القيامة."], ["يتخبّطه الشيطان", "يضربه الشيطان ضرباً غير منتظم."], ["من المسّ", "من الجنون."], ["موعظة", "أمر أو نهي بترك الربا."], ["فله ما سلف", "ليس عليه أن يردّ الأموال التي سبقت توبته."], ["يمحق الله الربا", "يُذهبه شيئاً فشيئاً حتى لا يبقى منه شيء، كمحاق القمر آخر الشهر."], ["ويُربي الصدقات", "يبارك في المال الذي أُخرجت منه، ويضاعف أجرها أضعافاً."], ["كفّار أثيم", "الكفّار: شديد الكفر بكل حق وخير، والأثيم: المنغمس في الذنوب لا يترك كبيرة ولا صغيرة إلا ارتكبها."]], "m": "لما حثّ الله على الصدقات ووعد عليها بعظيم الأجر، ذكر المرابين الذين يضاعفون مكاسبهم بالربا فيسدّون طرق البر، فذكر حالهم عند القيام من قبورهم: يقومون ويسقطون، حالهم حال من يُصرع في الدنيا بمسّ الجنون، علامة يُعرفون بها يوم القيامة. وسبب ذلك أنهم ردّوا حكم الله بتحريم الربا وقالوا: إنما البيع مثل الربا، فردّ عليهم: «وأحلّ الله البيع وحرّم الربا»، فما دام قد حرّمه فلا معنى للاعتراض؛ ونسوا أن الزيادة في البيع في قيمة سلعة تغلو وترخص، أما زيادة الربا فزيادة في الأجل فقط. ثم بيّن سبيل النجاة: فمن جاءه نهي ربه فانتهى فله ما سلف قبل التوبة، وأمره إلى الله، ومن عاد فأولئك أصحاب النار هم فيها خالدون. وأخبر أنه بعدله يمحق الربا وبفضله يُربي الصدقات، وأنه لا يحب كل كفّار أثيم.\nثم بشّر من آمن وعمل صالحاً وأقام الصلاة وآتى الزكاة بأن أجره وافٍ عند ربه يتسلّمه يوم القيامة، ولا خوف عليه ولا هو يحزن في الدنيا ولا في الآخرة.", "h": ["بيان عقوبة أكلة الربا يوم القيامة؛ لاستباحتهم الربا وعدم التوبة منه.", "حرمة الربا وكل مال حرام؛ لما جاء في الآية من الوعيد الشديد.", "صفة الحب لله تعالى، فهو يحب أولياءه أهل الإيمان والطاعة، ويكره أعداءه أهل الكفر والمعاصي من أكل الربا وغيره من الكبائر.", "حِلّ البيع إن تمّ على شروطه المبيّنة في كتب الفقه.", "من تاب من الربا قُبلت توبته، ويحلّ له ما أفاده منه قبل التوبة بشرط يأتي في الآيات بعدها.", "وعيد الله بمحق الربا، ووعده بإرباء الصدقة.", "بشرى الله لأهل الإيمان والعمل الصالح مع إقامة الصلاة وإيتاء الزكاة."], "k": "«يمحق الله الربا ويُربي الصدقات»… أيّهما أحرص عليه: ما يزيد في رصيدي، أم ما يبارك الله فيه؟"}, {"lbl": "الآيات ٢٧٨ – ٢٨١", "q": "يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ ٱتَّقُواْ ٱللَّهَ وَذَرُواْ مَا بَقِيَ مِنَ ٱلرِّبَوٰٓاْ إِن كُنتُم مُّؤۡمِنِينَ ﴿٢٧٨﴾ فَإِن لَّمۡ تَفۡعَلُواْ فَأۡذَنُواْ بِحَرۡبٖ مِّنَ ٱللَّهِ وَرَسُولِهِۦۖ وَإِن تُبۡتُمۡ فَلَكُمۡ رُءُوسُ أَمۡوَٰلِكُمۡ لَا تَظۡلِمُونَ وَلَا تُظۡلَمُونَ ﴿٢٧٩﴾ وَإِن كَانَ ذُو عُسۡرَةٖ فَنَظِرَةٌ إِلَىٰ مَيۡسَرَةٖۚ وَأَن تَصَدَّقُواْ خَيۡرٞ لَّكُمۡ إِن كُنتُمۡ تَعۡلَمُونَ ﴿٢٨٠﴾ وَٱتَّقُواْ يَوۡمٗا تُرۡجَعُونَ فِيهِ إِلَى ٱللَّهِۖ ثُمَّ تُوَفَّىٰ كُلُّ نَفۡسٖ مَّا كَسَبَتۡ وَهُمۡ لَا يُظۡلَمُونَ ﴿٢٨١﴾", "w": [["اتقوا الله", "خافوا عقابه بأن تجعلوا طاعته وقاية تقيكم غضبه."], ["وذروا ما بقي من الربا", "اتركوا ما بقي عندكم من المعاملات الربوية."], ["فأذنوا بحرب", "فاعلموا بحرب من الله ورسوله، ولا ينفعكم فيها سلاح، فإنكم المهزومون الهالكون."], ["فلكم رؤوس أموالكم", "بعد التوبة ليس لكم إلا رأس المال الذي عند المدين، فخذوه واتركوا زيادة الربا."], ["ذو عُسرة", "ذو شدّة وضائقة مالية."], ["فنظرة إلى ميسرة", "انتظار للمدين حتى ييسّر الله عليه فيعطيكم رأس مالكم."], ["وأن تصدّقوا", "وأن تتصدقوا على المعسر بترك ما لكم عليه، فذلك خير لكم."]], "m": "بمناسبة ذكر عقوبة أكلة الربا، نادى الله المؤمنين آمراً إياهم بتقواه، وبترك ما بقي عند بعضهم من المعاملات الربوية، مذكّراً بإيمانهم؛ إذ من شأن المؤمن أن يستجيب لنداء ربه. ثم هدّد المتباطئين: فإن لم تفعلوا فاعلموا بحرب ضروس من الله ورسوله. ثم بيّن طريق التوبة: إن تبتم فلكم رؤوس أموالكم لا غير؛ لا تَظلمون بأخذ زيادة، ولا تُظلمون بنقص من رأس المال. وإن كان المدين معسراً فالواجب انتظاره إلى ميسرته، وخير لكم أن تتصدقوا بالتنازل عن ديونكم كلها، تطهيراً لأموالكم التي لامسها الربا وتزكية لأنفسكم من آثاره. ثم ذكّر عباده بيوم القيامة وما فيه من حساب دقيق تُجزى فيه كل نفس ما كسبت وهم لا يُظلمون، وهذه الآية آخر ما نزل من السماء على رسول الله ﷺ.", "h": ["وجوب التوبة من الربا ومن كل المعاصي.", "المُصرّ على المعاملات الربوية يجب على الحاكم أن يحاربه بالضرب على يديه حتى يترك الربا.", "من تاب من الربا لا يُظلم بالأخذ من رأس ماله، بل يُعطاه كاملاً، إلا أن يتصدق بالتنازل عن ديونه الربوية فذلك خير له.", "وجوب ذكر الدار الآخرة والاستعداد لها بالإيمان والعمل الصالح وترك الربا والمعاصي."], "k": "«واتقوا يوماً تُرجعون فيه إلى الله»… آخر ما نزل من القرآن؛ فماذا أُعِدّ لذلك اليوم من الآن؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (41, 2, 282, 284, 'سورة البقرة ٢٨٢ – ٢٨٤', 'آية الدَّين، والرهن، وكتمان الشهادة', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 41) = $j$[{"lbl": "الآية ٢٨٢", "q": "يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ إِذَا تَدَايَنتُم بِدَيۡنٍ إِلَىٰٓ أَجَلٖ مُّسَمّٗى فَٱكۡتُبُوهُۚ وَلۡيَكۡتُب بَّيۡنَكُمۡ كَاتِبُۢ بِٱلۡعَدۡلِۚ وَلَا يَأۡبَ كَاتِبٌ أَن يَكۡتُبَ كَمَا عَلَّمَهُ ٱللَّهُۚ فَلۡيَكۡتُبۡ وَلۡيُمۡلِلِ ٱلَّذِي عَلَيۡهِ ٱلۡحَقُّ وَلۡيَتَّقِ ٱللَّهَ رَبَّهُۥ وَلَا يَبۡخَسۡ مِنۡهُ شَيۡـٔٗاۚ فَإِن كَانَ ٱلَّذِي عَلَيۡهِ ٱلۡحَقُّ سَفِيهًا أَوۡ ضَعِيفًا أَوۡ لَا يَسۡتَطِيعُ أَن يُمِلَّ هُوَ فَلۡيُمۡلِلۡ وَلِيُّهُۥ بِٱلۡعَدۡلِۚ وَٱسۡتَشۡهِدُواْ شَهِيدَيۡنِ مِن رِّجَالِكُمۡۖ فَإِن لَّمۡ يَكُونَا رَجُلَيۡنِ فَرَجُلٞ وَٱمۡرَأَتَانِ مِمَّن تَرۡضَوۡنَ مِنَ ٱلشُّهَدَآءِ أَن تَضِلَّ إِحۡدَىٰهُمَا فَتُذَكِّرَ إِحۡدَىٰهُمَا ٱلۡأُخۡرَىٰۚ وَلَا يَأۡبَ ٱلشُّهَدَآءُ إِذَا مَا دُعُواْۚ وَلَا تَسۡـَٔمُوٓاْ أَن تَكۡتُبُوهُ صَغِيرًا أَوۡ كَبِيرًا إِلَىٰٓ أَجَلِهِۦۚ ذَٰلِكُمۡ أَقۡسَطُ عِندَ ٱللَّهِ وَأَقۡوَمُ لِلشَّهَٰدَةِ وَأَدۡنَىٰٓ أَلَّا تَرۡتَابُوٓاْ إِلَّآ أَن تَكُونَ تِجَٰرَةً حَاضِرَةٗ تُدِيرُونَهَا بَيۡنَكُمۡ فَلَيۡسَ عَلَيۡكُمۡ جُنَاحٌ أَلَّا تَكۡتُبُوهَاۗ وَأَشۡهِدُوٓاْ إِذَا تَبَايَعۡتُمۡۚ وَلَا يُضَآرَّ كَاتِبٞ وَلَا شَهِيدٞۚ وَإِن تَفۡعَلُواْ فَإِنَّهُۥ فُسُوقُۢ بِكُمۡۗ وَٱتَّقُواْ ٱللَّهَۖ وَيُعَلِّمُكُمُ ٱللَّهُۗ وَٱللَّهُ بِكُلِّ شَيۡءٍ عَلِيمٞ ﴿٢٨٢﴾", "w": [["تداينتم", "داين بعضكم بعضاً في بيع أو شراء أو سَلَم أو قرض."], ["إلى أجل مسمّى", "وقت محدد بالأيام أو الشهور أو الأعوام."], ["بالعدل", "بلا زيادة ولا نقصان ولا غش، بل بالحق والإنصاف."], ["ولا يأبَ", "لا يمتنع الذي يُحسن الكتابة أن يكتب."], ["وليُملل الذي عليه الحق", "لأن إملاءه اعتراف منه وإقرار بما عليه."], ["ولا يبخس منه شيئاً", "لا ينقص من الدين الذي عليه شيئاً ولو قلّ."], ["سفيهاً أو ضعيفاً", "السفيه: الذي لا يحسن التصرفات المالية، والضعيف: العاجز عن الإملاء كالأخرس أو الشيخ الهرم."], ["وليّه", "من يلي أمره ويتولّى شؤونه لعجزه."], ["أن تضلّ إحداهما", "أن تنسى أو تخطئ."], ["ولا تسأموا", "لا تضجروا من الكتابة ولو كان الدين صغيراً."], ["أقسط عند الله", "أعدل في حكم الله وشرعه."], ["وأقوم للشهادة", "أثبت لها؛ لأن الكتابة لا تُنسى، والشهادة تُنسى أو يموت الشاهد أو يغيب."], ["وأدنى ألا ترتابوا", "أقرب ألا تشكّوا."], ["تديرونها بينكم", "تتعاطونها: البائع يعطي البضاعة والمشتري يعطي النقود، فلا حاجة إلى كتابتها."], ["ولا يُضارّ كاتب ولا شهيد", "بأن يُكلَّف ما لا يقدر عليه، كأن يُدعى ليشهد في مكان بعيد يشق عليه، أو يُطلب منه أن يكتب زوراً أو يشهد به."], ["فسوق بكم", "خروج عن طاعة ربكم، يلحقكم إثمه."]], "m": "لما حثّ الله على الصدقات، وحرّم الربا، ودعا إلى العفو عن المعسر بإسقاط الدين، وقد يتبادر إلى الذهن أن المال لا شأن له، جاءت آية الدين لتعطي المال حقه، فإنه قوام الحياة. فقرّرت واجب الحفاظ عليه: بكتابة الديون، والإشهاد عليها بمن تُرضى عدالتهم، رجلين مسلمين حرّين، فإن لم يكن رجلان قامت امرأتان مقام الرجل. وحثّ من يحسن الكتابة أن يكتب إذا كان في سعة من أمره، ونهى الشهود إذا دُعوا لأداء الشهادة أن يتخلّوا عنها، ونهى المتداينين أن يتركوا كتابة ديونهم ولو كانت قليلة. ورخّص رحمةً منه في ترك كتابة التجارة الحاضرة التي تُسلَّم فيها السلعة ويُقبض الثمن في المجلس، وأمر بالإشهاد على البيع. ونهى عن الإضرار بالكاتب والشاهد، كأن يُلزما بالكتابة أو الشهادة وهما في شغلهما، أو يُدعيا إلى مسافات بعيدة تشق عليهما، إذ عملهما تطوّع وفعل خير. وحذّر من كتمان الشهادة والجَور في الكتابة: «وإن تفعلوا فإنه فسوق بكم»، وأكّد ذلك بالأمر بتقواه، وكما علّمكم هذا العلم النافع ما زال يعلّمكم، وهو بكل شيء عليم.", "h": ["وجوب كتابة الديون، بيعاً كانت أو شراءً أو سلفاً أو قرضاً، وهو ما قرّره ابن جرير، وردّ القول بأنه إرشاد وندب.", "رعاية النعمة بشكرها؛ لقوله للكاتب: «كما علّمه الله فليكتب».", "جواز النيابة في الإملاء للعجز عنه.", "وجوب العدل والإنصاف في كل شيء، لا سيما في كتابة الديون المؤجلة.", "وجوب الإشهاد على الكتابة لتأكيدها وعدم نسيان قدر الدين وأجله.", "شهود المال لا يُقبل فيهم إلا رجلان عدلان من الأحرار المسلمين، والمرأتان المسلمتان تقومان مقام الرجل الواحد.", "الحرص على كتابة الديون والعزم على ذلك ولو كان الدين صغيراً.", "الرخصة في عدم كتابة التجارة الحاضرة المُدارة بين البائع والمشتري.", "وجوب الإشهاد على بيع العقارات والمزارع والمصانع مما هو ذو بال.", "حرمة الإضرار بالكاتب والشهيد.", "تقوى الله سبب للعلم وكسب المعرفة بإذن الله."], "k": "أطول آية في القرآن جاءت لتحفظ الحقوق… فهل عندي دَين لي أو عليّ لم أكتبه ولم أُعِدّ له؟"}, {"lbl": "الآيتان ٢٨٣ – ٢٨٤", "q": "۞وَإِن كُنتُمۡ عَلَىٰ سَفَرٖ وَلَمۡ تَجِدُواْ كَاتِبٗا فَرِهَٰنٞ مَّقۡبُوضَةٞۖ فَإِنۡ أَمِنَ بَعۡضُكُم بَعۡضٗا فَلۡيُؤَدِّ ٱلَّذِي ٱؤۡتُمِنَ أَمَٰنَتَهُۥ وَلۡيَتَّقِ ٱللَّهَ رَبَّهُۥۗ وَلَا تَكۡتُمُواْ ٱلشَّهَٰدَةَۚ وَمَن يَكۡتُمۡهَا فَإِنَّهُۥٓ ءَاثِمٞ قَلۡبُهُۥۗ وَٱللَّهُ بِمَا تَعۡمَلُونَ عَلِيمٞ ﴿٢٨٣﴾ لِّلَّهِ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِۗ وَإِن تُبۡدُواْ مَا فِيٓ أَنفُسِكُمۡ أَوۡ تُخۡفُوهُ يُحَاسِبۡكُم بِهِ ٱللَّهُۖ فَيَغۡفِرُ لِمَن يَشَآءُ وَيُعَذِّبُ مَن يَشَآءُۗ وَٱللَّهُ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٌ ﴿٢٨٤﴾", "w": [["على سفر", "خارجين من البلد إلى مسافة بعيدة."], ["ولم تجدوا كاتباً", "من يكتب لكم، أو لم تجدوا أدوات الكتابة."], ["فرهان مقبوضة", "فاعتاضوا عن الكتابة بالرهن، فيضع المدين رهناً لدى الدائن."], ["فإن أمن بعضكم بعضاً", "فلا حاجة إلى الرهن."], ["فليؤدِّ الذي اؤتمن أمانته", "فليعطِ الدين الذي اؤتمن عليه حيث تعذّرت الكتابة ولم يأخذ دائنه رهناً."], ["آثم قلبه", "لأن الكتمان من عمل القلب، فنُسب الإثم إليه."], ["وإن تُبدوا", "تُظهروا."]], "m": "لما أمر الله بالإشهاد والكتابة، أمر هنا عند تعذّرها، لعدم وجود كاتب أو أدوات الكتابة وذلك في السفر، أن يُستعاض عنها بالرهن: يضع المدين رهناً لدى دائنه يستوثق به دينه، وهذا عند الخوف وعدم الأمان. فإن أمن بعضكم بعضاً فلم تأخذوا رهاناً فليؤدِّ الذي اؤتمن أمانته وليتقِ الله ربه. ثم نهى الشهود نهياً جازماً عن كتمان شهادتهم، وبيّن عِظم هذا الذنب: «ومن يكتمها فإنه آثم قلبه»، وأعلم أنه عليم بما يعملون، وهذا تهديد ووعيد لكاتمي الشهادة وشهود الزور.\nثم أخبر أن له جميع ما في السماوات وما في الأرض خلقاً وملكاً وتصرفاً، فمن يُبدِ ما في نفسه من خير أو شر أو يُخفه يحاسبه به، ثم يغفر بعد الحساب لمن يشاء من أهل الإيمان والتقوى، ويعذّب من يشاء من أهل الشرك والمعاصي؛ لأن الجميع خلقه وملكه وعبيده.", "h": ["جواز أخذ الرهن في السفر والحضر توثيقاً من الدائن لدينه.", "جواز ترك أخذ الرهن إن حصل الأمن من سداد الدين.", "حرمة كتمان الشهادة والقول بالزور فيها، وأن ذلك من أكبر الكبائر.", "محاسبة العبد بما يخفيه في نفسه من الشك والشرك والنفاق وبغض أولياء الله وحب أعدائه، والعفو عن الهمّ بالخطيئة وحديث النفس من المؤمن الصادق ما لم يتكلم أو يعمل."], "k": "ما الذي أُخفيه في نفسي ولا يعلمه إلا الله؟ وهل أرضى أن أُحاسَب عليه؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 41;
insert into public.tdb_cards(topic, i, body) select 41, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآية ٢٨٢", "q": "يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ إِذَا تَدَايَنتُم بِدَيۡنٍ إِلَىٰٓ أَجَلٖ مُّسَمّٗى فَٱكۡتُبُوهُۚ وَلۡيَكۡتُب بَّيۡنَكُمۡ كَاتِبُۢ بِٱلۡعَدۡلِۚ وَلَا يَأۡبَ كَاتِبٌ أَن يَكۡتُبَ كَمَا عَلَّمَهُ ٱللَّهُۚ فَلۡيَكۡتُبۡ وَلۡيُمۡلِلِ ٱلَّذِي عَلَيۡهِ ٱلۡحَقُّ وَلۡيَتَّقِ ٱللَّهَ رَبَّهُۥ وَلَا يَبۡخَسۡ مِنۡهُ شَيۡـٔٗاۚ فَإِن كَانَ ٱلَّذِي عَلَيۡهِ ٱلۡحَقُّ سَفِيهًا أَوۡ ضَعِيفًا أَوۡ لَا يَسۡتَطِيعُ أَن يُمِلَّ هُوَ فَلۡيُمۡلِلۡ وَلِيُّهُۥ بِٱلۡعَدۡلِۚ وَٱسۡتَشۡهِدُواْ شَهِيدَيۡنِ مِن رِّجَالِكُمۡۖ فَإِن لَّمۡ يَكُونَا رَجُلَيۡنِ فَرَجُلٞ وَٱمۡرَأَتَانِ مِمَّن تَرۡضَوۡنَ مِنَ ٱلشُّهَدَآءِ أَن تَضِلَّ إِحۡدَىٰهُمَا فَتُذَكِّرَ إِحۡدَىٰهُمَا ٱلۡأُخۡرَىٰۚ وَلَا يَأۡبَ ٱلشُّهَدَآءُ إِذَا مَا دُعُواْۚ وَلَا تَسۡـَٔمُوٓاْ أَن تَكۡتُبُوهُ صَغِيرًا أَوۡ كَبِيرًا إِلَىٰٓ أَجَلِهِۦۚ ذَٰلِكُمۡ أَقۡسَطُ عِندَ ٱللَّهِ وَأَقۡوَمُ لِلشَّهَٰدَةِ وَأَدۡنَىٰٓ أَلَّا تَرۡتَابُوٓاْ إِلَّآ أَن تَكُونَ تِجَٰرَةً حَاضِرَةٗ تُدِيرُونَهَا بَيۡنَكُمۡ فَلَيۡسَ عَلَيۡكُمۡ جُنَاحٌ أَلَّا تَكۡتُبُوهَاۗ وَأَشۡهِدُوٓاْ إِذَا تَبَايَعۡتُمۡۚ وَلَا يُضَآرَّ كَاتِبٞ وَلَا شَهِيدٞۚ وَإِن تَفۡعَلُواْ فَإِنَّهُۥ فُسُوقُۢ بِكُمۡۗ وَٱتَّقُواْ ٱللَّهَۖ وَيُعَلِّمُكُمُ ٱللَّهُۗ وَٱللَّهُ بِكُلِّ شَيۡءٍ عَلِيمٞ ﴿٢٨٢﴾", "w": [["تداينتم", "داين بعضكم بعضاً في بيع أو شراء أو سَلَم أو قرض."], ["إلى أجل مسمّى", "وقت محدد بالأيام أو الشهور أو الأعوام."], ["بالعدل", "بلا زيادة ولا نقصان ولا غش، بل بالحق والإنصاف."], ["ولا يأبَ", "لا يمتنع الذي يُحسن الكتابة أن يكتب."], ["وليُملل الذي عليه الحق", "لأن إملاءه اعتراف منه وإقرار بما عليه."], ["ولا يبخس منه شيئاً", "لا ينقص من الدين الذي عليه شيئاً ولو قلّ."], ["سفيهاً أو ضعيفاً", "السفيه: الذي لا يحسن التصرفات المالية، والضعيف: العاجز عن الإملاء كالأخرس أو الشيخ الهرم."], ["وليّه", "من يلي أمره ويتولّى شؤونه لعجزه."], ["أن تضلّ إحداهما", "أن تنسى أو تخطئ."], ["ولا تسأموا", "لا تضجروا من الكتابة ولو كان الدين صغيراً."], ["أقسط عند الله", "أعدل في حكم الله وشرعه."], ["وأقوم للشهادة", "أثبت لها؛ لأن الكتابة لا تُنسى، والشهادة تُنسى أو يموت الشاهد أو يغيب."], ["وأدنى ألا ترتابوا", "أقرب ألا تشكّوا."], ["تديرونها بينكم", "تتعاطونها: البائع يعطي البضاعة والمشتري يعطي النقود، فلا حاجة إلى كتابتها."], ["ولا يُضارّ كاتب ولا شهيد", "بأن يُكلَّف ما لا يقدر عليه، كأن يُدعى ليشهد في مكان بعيد يشق عليه، أو يُطلب منه أن يكتب زوراً أو يشهد به."], ["فسوق بكم", "خروج عن طاعة ربكم، يلحقكم إثمه."]], "m": "لما حثّ الله على الصدقات، وحرّم الربا، ودعا إلى العفو عن المعسر بإسقاط الدين، وقد يتبادر إلى الذهن أن المال لا شأن له، جاءت آية الدين لتعطي المال حقه، فإنه قوام الحياة. فقرّرت واجب الحفاظ عليه: بكتابة الديون، والإشهاد عليها بمن تُرضى عدالتهم، رجلين مسلمين حرّين، فإن لم يكن رجلان قامت امرأتان مقام الرجل. وحثّ من يحسن الكتابة أن يكتب إذا كان في سعة من أمره، ونهى الشهود إذا دُعوا لأداء الشهادة أن يتخلّوا عنها، ونهى المتداينين أن يتركوا كتابة ديونهم ولو كانت قليلة. ورخّص رحمةً منه في ترك كتابة التجارة الحاضرة التي تُسلَّم فيها السلعة ويُقبض الثمن في المجلس، وأمر بالإشهاد على البيع. ونهى عن الإضرار بالكاتب والشاهد، كأن يُلزما بالكتابة أو الشهادة وهما في شغلهما، أو يُدعيا إلى مسافات بعيدة تشق عليهما، إذ عملهما تطوّع وفعل خير. وحذّر من كتمان الشهادة والجَور في الكتابة: «وإن تفعلوا فإنه فسوق بكم»، وأكّد ذلك بالأمر بتقواه، وكما علّمكم هذا العلم النافع ما زال يعلّمكم، وهو بكل شيء عليم.", "h": ["وجوب كتابة الديون، بيعاً كانت أو شراءً أو سلفاً أو قرضاً، وهو ما قرّره ابن جرير، وردّ القول بأنه إرشاد وندب.", "رعاية النعمة بشكرها؛ لقوله للكاتب: «كما علّمه الله فليكتب».", "جواز النيابة في الإملاء للعجز عنه.", "وجوب العدل والإنصاف في كل شيء، لا سيما في كتابة الديون المؤجلة.", "وجوب الإشهاد على الكتابة لتأكيدها وعدم نسيان قدر الدين وأجله.", "شهود المال لا يُقبل فيهم إلا رجلان عدلان من الأحرار المسلمين، والمرأتان المسلمتان تقومان مقام الرجل الواحد.", "الحرص على كتابة الديون والعزم على ذلك ولو كان الدين صغيراً.", "الرخصة في عدم كتابة التجارة الحاضرة المُدارة بين البائع والمشتري.", "وجوب الإشهاد على بيع العقارات والمزارع والمصانع مما هو ذو بال.", "حرمة الإضرار بالكاتب والشهيد.", "تقوى الله سبب للعلم وكسب المعرفة بإذن الله."], "k": "أطول آية في القرآن جاءت لتحفظ الحقوق… فهل عندي دَين لي أو عليّ لم أكتبه ولم أُعِدّ له؟"}, {"lbl": "الآيتان ٢٨٣ – ٢٨٤", "q": "۞وَإِن كُنتُمۡ عَلَىٰ سَفَرٖ وَلَمۡ تَجِدُواْ كَاتِبٗا فَرِهَٰنٞ مَّقۡبُوضَةٞۖ فَإِنۡ أَمِنَ بَعۡضُكُم بَعۡضٗا فَلۡيُؤَدِّ ٱلَّذِي ٱؤۡتُمِنَ أَمَٰنَتَهُۥ وَلۡيَتَّقِ ٱللَّهَ رَبَّهُۥۗ وَلَا تَكۡتُمُواْ ٱلشَّهَٰدَةَۚ وَمَن يَكۡتُمۡهَا فَإِنَّهُۥٓ ءَاثِمٞ قَلۡبُهُۥۗ وَٱللَّهُ بِمَا تَعۡمَلُونَ عَلِيمٞ ﴿٢٨٣﴾ لِّلَّهِ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِۗ وَإِن تُبۡدُواْ مَا فِيٓ أَنفُسِكُمۡ أَوۡ تُخۡفُوهُ يُحَاسِبۡكُم بِهِ ٱللَّهُۖ فَيَغۡفِرُ لِمَن يَشَآءُ وَيُعَذِّبُ مَن يَشَآءُۗ وَٱللَّهُ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٌ ﴿٢٨٤﴾", "w": [["على سفر", "خارجين من البلد إلى مسافة بعيدة."], ["ولم تجدوا كاتباً", "من يكتب لكم، أو لم تجدوا أدوات الكتابة."], ["فرهان مقبوضة", "فاعتاضوا عن الكتابة بالرهن، فيضع المدين رهناً لدى الدائن."], ["فإن أمن بعضكم بعضاً", "فلا حاجة إلى الرهن."], ["فليؤدِّ الذي اؤتمن أمانته", "فليعطِ الدين الذي اؤتمن عليه حيث تعذّرت الكتابة ولم يأخذ دائنه رهناً."], ["آثم قلبه", "لأن الكتمان من عمل القلب، فنُسب الإثم إليه."], ["وإن تُبدوا", "تُظهروا."]], "m": "لما أمر الله بالإشهاد والكتابة، أمر هنا عند تعذّرها، لعدم وجود كاتب أو أدوات الكتابة وذلك في السفر، أن يُستعاض عنها بالرهن: يضع المدين رهناً لدى دائنه يستوثق به دينه، وهذا عند الخوف وعدم الأمان. فإن أمن بعضكم بعضاً فلم تأخذوا رهاناً فليؤدِّ الذي اؤتمن أمانته وليتقِ الله ربه. ثم نهى الشهود نهياً جازماً عن كتمان شهادتهم، وبيّن عِظم هذا الذنب: «ومن يكتمها فإنه آثم قلبه»، وأعلم أنه عليم بما يعملون، وهذا تهديد ووعيد لكاتمي الشهادة وشهود الزور.\nثم أخبر أن له جميع ما في السماوات وما في الأرض خلقاً وملكاً وتصرفاً، فمن يُبدِ ما في نفسه من خير أو شر أو يُخفه يحاسبه به، ثم يغفر بعد الحساب لمن يشاء من أهل الإيمان والتقوى، ويعذّب من يشاء من أهل الشرك والمعاصي؛ لأن الجميع خلقه وملكه وعبيده.", "h": ["جواز أخذ الرهن في السفر والحضر توثيقاً من الدائن لدينه.", "جواز ترك أخذ الرهن إن حصل الأمن من سداد الدين.", "حرمة كتمان الشهادة والقول بالزور فيها، وأن ذلك من أكبر الكبائر.", "محاسبة العبد بما يخفيه في نفسه من الشك والشرك والنفاق وبغض أولياء الله وحب أعدائه، والعفو عن الهمّ بالخطيئة وحديث النفس من المؤمن الصادق ما لم يتكلم أو يعمل."], "k": "ما الذي أُخفيه في نفسي ولا يعلمه إلا الله؟ وهل أرضى أن أُحاسَب عليه؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (42, 2, 285, 286, 'سورة البقرة ٢٨٥ – ٢٨٦', 'خواتيم سورة البقرة', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 42) = $j$[{"lbl": "الآيتان ٢٨٥ – ٢٨٦", "q": "ءَامَنَ ٱلرَّسُولُ بِمَآ أُنزِلَ إِلَيۡهِ مِن رَّبِّهِۦ وَٱلۡمُؤۡمِنُونَۚ كُلٌّ ءَامَنَ بِٱللَّهِ وَمَلَـٰٓئِكَتِهِۦ وَكُتُبِهِۦ وَرُسُلِهِۦ لَا نُفَرِّقُ بَيۡنَ أَحَدٖ مِّن رُّسُلِهِۦۚ وَقَالُواْ سَمِعۡنَا وَأَطَعۡنَاۖ غُفۡرَانَكَ رَبَّنَا وَإِلَيۡكَ ٱلۡمَصِيرُ ﴿٢٨٥﴾ لَا يُكَلِّفُ ٱللَّهُ نَفۡسًا إِلَّا وُسۡعَهَاۚ لَهَا مَا كَسَبَتۡ وَعَلَيۡهَا مَا ٱكۡتَسَبَتۡۗ رَبَّنَا لَا تُؤَاخِذۡنَآ إِن نَّسِينَآ أَوۡ أَخۡطَأۡنَاۚ رَبَّنَا وَلَا تَحۡمِلۡ عَلَيۡنَآ إِصۡرٗا كَمَا حَمَلۡتَهُۥ عَلَى ٱلَّذِينَ مِن قَبۡلِنَاۚ رَبَّنَا وَلَا تُحَمِّلۡنَا مَا لَا طَاقَةَ لَنَا بِهِۦۖ وَٱعۡفُ عَنَّا وَٱغۡفِرۡ لَنَا وَٱرۡحَمۡنَآۚ أَنتَ مَوۡلَىٰنَا فَٱنصُرۡنَا عَلَى ٱلۡقَوۡمِ ٱلۡكَٰفِرِينَ ﴿٢٨٦﴾", "w": [["آمن", "صدّق جازماً بصحة الخبر، ولم يتردد أو يشك فيه قط."], ["الرسول", "نبينا محمد ﷺ."], ["كلٌّ", "كلٌّ من الرسول والمؤمنين."], ["لا نفرّق بين أحد من رسله", "نؤمن بهم جميعاً، ولا نكون كاليهود والنصارى نؤمن ببعض ونكفر ببعض."], ["سمعنا", "سماع فهم واستجابة وطاعة."], ["وإليك المصير", "المرجع، أي رجوعنا إليك يا ربنا فاغفر لنا."], ["لا يكلّف الله نفساً", "التكليف: الإلزام بما فيه كلفة ومشقة تُحتمل."], ["لها ما كسبت", "من الخير."], ["وعليها ما اكتسبت", "من الشر."], ["لا تؤاخذنا", "لا تعاقبنا."], ["إن نسينا", "فتركنا ما أمرتنا به أو فعلنا ما نهيتنا عنه نسياناً غير عمد."], ["أو أخطأنا", "فعلنا غير ما أمرتنا خطأً بلا إرادة منا ولا عزيمة."], ["إصراً", "تكليفاً شاقاً يثقل علينا ويحبسنا عن العمل."], ["مولانا", "مالكنا وسيدنا ومتولّي أمرنا، لا مولى لنا سواك."]], "m": "ورد أنه لما نزلت: «وإن تُبدوا ما في أنفسكم أو تخفوه يحاسبكم به الله» اضطربت نفوس المؤمنين، وقالوا: من ينجو منا إذا كنا نؤاخذ بما يخفى في أنفسنا من الهمّ والوسواس وحديث النفس؟ فأمرهم الرسول ﷺ بالرضا بحكم الله والتسليم له، وأن يقولوا: سمعنا وأطعنا، ولا يكونوا كاليهود الذين قالوا: سمعنا وعصينا. فلما قالوها صادقين أنزل الله هاتين الآيتين، فأخبر عن إيمانهم مقروناً بإيمان نبيهم تكريماً لهم وتطميناً: آمن الرسول والمؤمنون، كلٌّ آمن بالله وملائكته وكتبه ورسله لا يفرّقون بين أحد منهم، وقالوا: سمعنا وأطعنا غفرانك ربنا وإليك المصير. وأخبرهم أنه برحمته وحكمته لا يكلّف نفساً إلا ما تتسع له طاقتها، لها ما كسبت من الخير فتُجزى به، وعليها ما اكتسبت من الشر إلا أن يعفو عنها. وعلّمهم كيف يدعونه: «ربنا لا تؤاخذنا إن نسينا أو أخطأنا…» إلى آخرها، وقد عفا عنهم في النسيان والخطأ، وخفّف عنهم في التشريع فما جعل عليهم في الدين من حرج، وعفا عنهم وغفر لهم ورحمهم، ونصرهم على الكافرين بالحجة والبيان وفي المعارك.", "h": ["تقرير أركان الإيمان: الإيمان بالله وملائكته وكتبه ورسله.", "وجوب الإيمان بكافة الرسل، وحرمة الإيمان ببعضهم وترك بعض، وهو كفر والعياذ بالله.", "وجوب طاعة الله ورسوله، والتسليم والرضا بما شرعا، وحرمة ردّ شيء من ذلك.", "رفع الحرج عن هذه الأمة رحمةً بها.", "عدم المؤاخذة بالنسيان أو الخطأ، فمن نسي فأكل أو شرب وهو صائم فلا إثم عليه، أو أخطأ فقتل فلا إثم عليه.", "العفو عن حديث النفس ما لم يتكلم المؤمن أو يعمل.", "تعليم هذا الدعاء واستحباب الدعاء به اقتداءً بالرسول ﷺ وأصحابه، وقد ورد أن من قرأ هاتين الآيتين عند النوم كفتاه."], "k": "«سمعنا وأطعنا»… ما الأمر الذي أعرفه من ديني ولم أقل له بعدُ «سمعنا وأطعنا» بعملي؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 42;
insert into public.tdb_cards(topic, i, body) select 42, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيتان ٢٨٥ – ٢٨٦", "q": "ءَامَنَ ٱلرَّسُولُ بِمَآ أُنزِلَ إِلَيۡهِ مِن رَّبِّهِۦ وَٱلۡمُؤۡمِنُونَۚ كُلٌّ ءَامَنَ بِٱللَّهِ وَمَلَـٰٓئِكَتِهِۦ وَكُتُبِهِۦ وَرُسُلِهِۦ لَا نُفَرِّقُ بَيۡنَ أَحَدٖ مِّن رُّسُلِهِۦۚ وَقَالُواْ سَمِعۡنَا وَأَطَعۡنَاۖ غُفۡرَانَكَ رَبَّنَا وَإِلَيۡكَ ٱلۡمَصِيرُ ﴿٢٨٥﴾ لَا يُكَلِّفُ ٱللَّهُ نَفۡسًا إِلَّا وُسۡعَهَاۚ لَهَا مَا كَسَبَتۡ وَعَلَيۡهَا مَا ٱكۡتَسَبَتۡۗ رَبَّنَا لَا تُؤَاخِذۡنَآ إِن نَّسِينَآ أَوۡ أَخۡطَأۡنَاۚ رَبَّنَا وَلَا تَحۡمِلۡ عَلَيۡنَآ إِصۡرٗا كَمَا حَمَلۡتَهُۥ عَلَى ٱلَّذِينَ مِن قَبۡلِنَاۚ رَبَّنَا وَلَا تُحَمِّلۡنَا مَا لَا طَاقَةَ لَنَا بِهِۦۖ وَٱعۡفُ عَنَّا وَٱغۡفِرۡ لَنَا وَٱرۡحَمۡنَآۚ أَنتَ مَوۡلَىٰنَا فَٱنصُرۡنَا عَلَى ٱلۡقَوۡمِ ٱلۡكَٰفِرِينَ ﴿٢٨٦﴾", "w": [["آمن", "صدّق جازماً بصحة الخبر، ولم يتردد أو يشك فيه قط."], ["الرسول", "نبينا محمد ﷺ."], ["كلٌّ", "كلٌّ من الرسول والمؤمنين."], ["لا نفرّق بين أحد من رسله", "نؤمن بهم جميعاً، ولا نكون كاليهود والنصارى نؤمن ببعض ونكفر ببعض."], ["سمعنا", "سماع فهم واستجابة وطاعة."], ["وإليك المصير", "المرجع، أي رجوعنا إليك يا ربنا فاغفر لنا."], ["لا يكلّف الله نفساً", "التكليف: الإلزام بما فيه كلفة ومشقة تُحتمل."], ["لها ما كسبت", "من الخير."], ["وعليها ما اكتسبت", "من الشر."], ["لا تؤاخذنا", "لا تعاقبنا."], ["إن نسينا", "فتركنا ما أمرتنا به أو فعلنا ما نهيتنا عنه نسياناً غير عمد."], ["أو أخطأنا", "فعلنا غير ما أمرتنا خطأً بلا إرادة منا ولا عزيمة."], ["إصراً", "تكليفاً شاقاً يثقل علينا ويحبسنا عن العمل."], ["مولانا", "مالكنا وسيدنا ومتولّي أمرنا، لا مولى لنا سواك."]], "m": "ورد أنه لما نزلت: «وإن تُبدوا ما في أنفسكم أو تخفوه يحاسبكم به الله» اضطربت نفوس المؤمنين، وقالوا: من ينجو منا إذا كنا نؤاخذ بما يخفى في أنفسنا من الهمّ والوسواس وحديث النفس؟ فأمرهم الرسول ﷺ بالرضا بحكم الله والتسليم له، وأن يقولوا: سمعنا وأطعنا، ولا يكونوا كاليهود الذين قالوا: سمعنا وعصينا. فلما قالوها صادقين أنزل الله هاتين الآيتين، فأخبر عن إيمانهم مقروناً بإيمان نبيهم تكريماً لهم وتطميناً: آمن الرسول والمؤمنون، كلٌّ آمن بالله وملائكته وكتبه ورسله لا يفرّقون بين أحد منهم، وقالوا: سمعنا وأطعنا غفرانك ربنا وإليك المصير. وأخبرهم أنه برحمته وحكمته لا يكلّف نفساً إلا ما تتسع له طاقتها، لها ما كسبت من الخير فتُجزى به، وعليها ما اكتسبت من الشر إلا أن يعفو عنها. وعلّمهم كيف يدعونه: «ربنا لا تؤاخذنا إن نسينا أو أخطأنا…» إلى آخرها، وقد عفا عنهم في النسيان والخطأ، وخفّف عنهم في التشريع فما جعل عليهم في الدين من حرج، وعفا عنهم وغفر لهم ورحمهم، ونصرهم على الكافرين بالحجة والبيان وفي المعارك.", "h": ["تقرير أركان الإيمان: الإيمان بالله وملائكته وكتبه ورسله.", "وجوب الإيمان بكافة الرسل، وحرمة الإيمان ببعضهم وترك بعض، وهو كفر والعياذ بالله.", "وجوب طاعة الله ورسوله، والتسليم والرضا بما شرعا، وحرمة ردّ شيء من ذلك.", "رفع الحرج عن هذه الأمة رحمةً بها.", "عدم المؤاخذة بالنسيان أو الخطأ، فمن نسي فأكل أو شرب وهو صائم فلا إثم عليه، أو أخطأ فقتل فلا إثم عليه.", "العفو عن حديث النفس ما لم يتكلم المؤمن أو يعمل.", "تعليم هذا الدعاء واستحباب الدعاء به اقتداءً بالرسول ﷺ وأصحابه، وقد ورد أن من قرأ هاتين الآيتين عند النوم كفتاه."], "k": "«سمعنا وأطعنا»… ما الأمر الذي أعرفه من ديني ولم أقل له بعدُ «سمعنا وأطعنا» بعملي؟"}]$j$::jsonb) with ordinality x(e, i);
select n, title, pub, (select count(*) from public.tdb_cards c where c.topic=t.n) cards from public.tdb_topics t where n>=36 order by n;